insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('diwali', 'Diwali', 'Deepavali', 'The festival of lights', 'Five days of lamps, sweets and family visits marking the victory of light over darkness, celebrated by Hindus, Jains, Sikhs and some Buddhists.', (select id from public.regions where slug = 'south-asia'), 'light', 'Hindu, Jain, Sikh and Newar Buddhist communities worldwide', '{"kind":"table","calendar":"Hindu lunisolar calendar (new moon of Kartik)","typicalMonths":[10,11]}'::jsonb, 'Diwali follows the lunar calendar, so it moves each year between mid-October and mid-November. The exact day can differ by region and by the almanac a community follows.', 'Diwali grew out of autumn harvest and lamp festivals described in early Sanskrit texts. Different traditions attach different stories to it: in much of north India it recalls Rama''s return to Ayodhya, in the south Krishna''s defeat of Narakasura, for Jains the liberation of Mahavira, and for Sikhs Bandi Chhor Divas, the release of Guru Hargobind.', 'Across these traditions the shared idea is renewal: light over darkness, knowledge over ignorance, and a fresh start for the household and the business year.', array['Remove your shoes before entering a home or temple.', 'A box of sweets or dried fruit is a welcome gift for hosts.', 'Check local rules before using fireworks; many cities restrict them for air quality.']::text[], array['bollywood', 'classical', 'traditional']::text[], array['#33143a', '#f0a030', '#dcc898']::text[], 26.8, 82.2, 'https://en.wikipedia.org/wiki/Diwali', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
