insert into public.festival_dates (festival_id, starts_on, ends_on, status, note, source_url, last_checked_at) values ((select id from public.festivals where slug = 'diwali'), '2027-10-29', '2027-10-29', 'verified', 'Main day (Lakshmi Puja). The five-day festival runs from about 27 to 31 October, and some communities outside India observe the main day a day earlier.', 'https://www.drikpanchang.com/hindu-festivals/diwali/diwali.html', '2026-11-16T00:00:00Z'::timestamptz) on conflict (festival_id, starts_on) do update set ends_on = excluded.ends_on, status = excluded.status, note = excluded.note, source_url = excluded.source_url, last_checked_at = excluded.last_checked_at;
insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('holi', 'Holi', null, 'The festival of colours', 'A spring festival where people gather outdoors to throw coloured powder and water, preceded by a bonfire the night before.', (select id from public.regions where slug = 'south-asia'), 'spring', 'Hindu communities, and widely as a social festival across South Asia and the diaspora', '{"kind":"table","calendar":"Hindu lunisolar calendar (full moon of Phalguna)","typicalMonths":[2,3]}'::jsonb, 'Holi falls on the full moon of the month of Phalguna, in late February or March. Local observance can differ by a day.', 'Holi is mentioned in early Indian literature as a spring celebration. It is associated with the story of Prahlada and Holika, remembered in the bonfire, and with the playful stories of Radha and Krishna in the Braj region.', 'It marks the end of winter and is a day when ordinary social distance is relaxed: neighbours, friends and strangers play together.', array['Ask before putting colour on someone; not everyone wants to play.', 'Use skin-safe, plant-based colours and protect eyes.', 'Wear clothes you are happy to stain.']::text[], array['bollywood', 'folk']::text[], array['#fbf6ea', '#c2267a', '#0e8a6b']::text[], 27.5, 77.7, 'https://en.wikipedia.org/wiki/Holi', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
