insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('durga-puja', 'Durga Puja', null, 'Bengal''s autumn homecoming of the goddess', 'Days of worship, art and street life centred on elaborately crafted images of the goddess Durga, at its grandest in Kolkata.', (select id from public.regions where slug = 'south-asia'), 'faith', 'Bengali Hindu communities, with related autumn festivals across South Asia', '{"kind":"table","calendar":"Hindu lunisolar calendar (bright fortnight of Ashwin)","typicalMonths":[9,10]}'::jsonb, 'Durga Puja falls in September or October. The principal days run from Shashthi to Vijaya Dashami.', 'Community-funded (sarbojanin) pujas spread through Bengal in the early twentieth century, building on older household celebrations. Durga Puja in Kolkata was inscribed on UNESCO''s Representative List of the Intangible Cultural Heritage of Humanity in 2021.', 'It celebrates the goddess Durga''s victory over the buffalo demon Mahishasura and, in Bengal, her yearly visit to her parental home.', array['Pandals are places of worship as well as art; dress modestly and follow queue guidance.', 'Ask before photographing rituals at close range.']::text[], array['traditional', 'classical']::text[], array['#b93626', '#fbf6ea', '#f0a030']::text[], 22.57, 88.36, 'https://en.wikipedia.org/wiki/Durga_Puja', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
