insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('ganesh-chaturthi', 'Ganesh Chaturthi', null, 'Ten days with the remover of obstacles', 'Clay images of Ganesha are welcomed into homes and neighbourhoods, honoured for up to ten days, then carried in procession to water.', (select id from public.regions where slug = 'south-asia'), 'faith', 'Hindu communities, especially in Maharashtra, Goa, Karnataka and Telangana', '{"kind":"table","calendar":"Hindu lunisolar calendar (fourth day of the bright half of Bhadrapada)","typicalMonths":[8,9]}'::jsonb, 'Falls in August or September. Households keep the image for one and a half, five, seven or ten days.', 'A household festival for centuries, it became a large public celebration in Maharashtra in the 1890s, when Bal Gangadhar Tilak encouraged community gatherings around it.', 'Ganesha is honoured as the god of beginnings and wisdom, invoked before new ventures.', array['Choose natural clay images and avoid plaster of Paris, which pollutes water.', 'Many cities provide artificial ponds for immersion; use them where offered.']::text[], array['traditional', 'bollywood']::text[], array['#f0a030', '#b93626', '#fbf6ea']::text[], 19.08, 72.88, 'https://en.wikipedia.org/wiki/Ganesh_Chaturthi', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
