insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('onam', 'Onam', null, 'Kerala''s harvest welcome for King Mahabali', 'A ten-day harvest festival of flower carpets, boat races and a vegetarian banquet served on banana leaves.', (select id from public.regions where slug = 'south-asia'), 'harvest', 'Malayali communities of every faith, in Kerala and abroad', '{"kind":"table","calendar":"Malayalam calendar (Thiruvonam in the month of Chingam)","typicalMonths":[8,9]}'::jsonb, 'Onam falls in August or September. Thiruvonam is the most important of its ten days.', 'Onam is tied to the legend of Mahabali, a just king whose yearly return to his people is welcomed with abundance. It is Kerala''s official state festival.', 'It celebrates the harvest and an ideal of a fair and prosperous society shared by everyone.', array['A sadya is eaten with the right hand from a banana leaf; fold the leaf towards you when finished.']::text[], array['traditional', 'classical']::text[], array['#fbf6ea', '#dca92b', '#0e5a48']::text[], 9.97, 76.28, 'https://en.wikipedia.org/wiki/Onam', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
