insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('pongal', 'Pongal', null, 'The Tamil harvest thanksgiving', 'Four days of thanks to the sun, the land and cattle, named after the sweet rice that is boiled until it overflows.', (select id from public.regions where slug = 'south-asia'), 'harvest', 'Tamil communities in India, Sri Lanka, Malaysia, Singapore and the diaspora', '{"kind":"table","calendar":"Tamil solar calendar (first day of Thai)","typicalMonths":[1]}'::jsonb, 'Thai Pongal follows the solar calendar and falls on 14 or 15 January. FESTIVA shows the four-day festival; Bhogi is the day before Thai Pongal.', 'Pongal is an old harvest festival of the Tamil country, tied to the sun''s northward turn and the first rice of the season.', 'The overflowing pot is a sign of abundance; the days that follow honour cattle and family ties.', array['The first pongal is offered to the sun before anyone eats.']::text[], array['traditional', 'classical']::text[], array['#f2e7cf', '#b93626', '#dca92b']::text[], 9.93, 78.12, 'https://en.wikipedia.org/wiki/Pongal_(festival)', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
