insert into public.festival_dates (festival_id, starts_on, ends_on, status, note, source_url, last_checked_at) values ((select id from public.festivals where slug = 'pongal'), '2027-01-14', '2027-01-17', 'verified', 'Bhogi on 14 January, Thai Pongal (the main day) on Friday 15 January in India and Sri Lanka, then Mattu and Kaanum Pongal. In North America and the UK the panchang gives Thai Pongal on 14 January.', 'https://www.drikpanchang.com/festivals/pongal/thai-pongal-date-time.html?year=2027', '2026-11-16T00:00:00Z'::timestamptz) on conflict (festival_id, starts_on) do update set ends_on = excluded.ends_on, status = excluded.status, note = excluded.note, source_url = excluded.source_url, last_checked_at = excluded.last_checked_at;
insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('eid-al-fitr', 'Eid al-Fitr', null, 'The festival of breaking the fast', 'The celebration that ends Ramadan: morning prayers, charity, new clothes, visits and a table of sweets.', (select id from public.regions where slug = 'middle-east'), 'faith', 'Muslim communities worldwide', '{"kind":"table","calendar":"Islamic lunar calendar (1 Shawwal)","typicalMonths":[2,3]}'::jsonb, 'The Islamic year is about eleven days shorter than the solar year, so Eid moves earlier each year. The start is confirmed by moon sighting and can differ between countries.', 'Eid al-Fitr dates to the earliest Muslim community in Medina and is one of the two major festivals of Islam.', 'It is a day of gratitude after a month of fasting, and of making sure everyone can celebrate through the giving of zakat al-fitr.', array['Greet people with ''Eid Mubarak''.', 'If invited to a home, a gift of sweets or dates is appreciated.']::text[], array['traditional', 'world']::text[], array['#0e5a48', '#dcc898', '#fbf6ea']::text[], 30.04, 31.24, 'https://en.wikipedia.org/wiki/Eid_al-Fitr', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
