insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('eid-al-adha', 'Eid al-Adha', null, 'The festival of sacrifice', 'The second great festival of Islam, at the close of the Hajj pilgrimage, centred on prayer, sacrifice and sharing food.', (select id from public.regions where slug = 'middle-east'), 'faith', 'Muslim communities worldwide', '{"kind":"table","calendar":"Islamic lunar calendar (10 Dhu al-Hijjah)","typicalMonths":[5,6]}'::jsonb, 'Confirmed by moon sighting about ten days beforehand; the day can differ between countries.', 'The festival recalls Ibrahim''s willingness to sacrifice his son in obedience to God, and coincides with the final rites of the Hajj.', 'It is about devotion and generosity: the meat of the sacrifice is traditionally shared between family, friends and people in need.', array['Many families now arrange the sacrifice through a charity; it is fine to ask a host how they observe it.']::text[], array['traditional', 'world']::text[], array['#083b30', '#dcc898', '#f0a030']::text[], 21.42, 39.83, 'https://en.wikipedia.org/wiki/Eid_al-Adha', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
