insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('lunar-new-year', 'Lunar New Year', 'Spring Festival, Tết, Seollal', 'Fifteen days to begin the year together', 'The most important holiday in much of East and Southeast Asia: a reunion dinner, red envelopes, and visits that continue until the Lantern Festival.', (select id from public.regions where slug = 'east-asia'), 'new-year', 'Chinese, Vietnamese, Korean and other communities across Asia and the diaspora', '{"kind":"table","calendar":"Chinese lunisolar calendar (first new moon of the year)","typicalMonths":[1,2]}'::jsonb, 'New Year''s Day falls between 21 January and 20 February. Vietnamese and Korean calendars usually agree with the Chinese date but can occasionally differ by a day.', 'The festival has agrarian roots more than two thousand years old, tied to honouring ancestors and household gods at the turn of the year.', 'It is about family reunion and setting the tone for the year: debts settled, homes cleaned, and good wishes exchanged.', array['Give money in even amounts in a red envelope, with both hands.', 'Avoid giving clocks or sharp objects as gifts.']::text[], array['traditional', 'k-pop', 'world']::text[], array['#b93626', '#dca92b', '#fbf6ea']::text[], 39.9, 116.4, 'https://en.wikipedia.org/wiki/Lunar_New_Year', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
