insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('mid-autumn-festival', 'Mid-Autumn Festival', 'Zhongqiu, Tết Trung Thu, Chuseok', 'A full moon, shared', 'Families gather under the harvest moon to share mooncakes, light lanterns and give thanks.', (select id from public.regions where slug = 'east-asia'), 'harvest', 'Chinese, Vietnamese, Korean and neighbouring communities', '{"kind":"table","calendar":"Chinese lunisolar calendar (15th day of the 8th month)","typicalMonths":[9,10]}'::jsonb, 'Falls on the full moon of the eighth lunar month, in September or early October.', 'Moon worship at the autumn harvest is recorded from early Chinese dynasties; the festival took its present family form by the Tang and Song periods.', 'The round moon stands for reunion. Those who cannot be together are said to share the same moon.', array['Mooncakes are rich; they are meant to be shared in small pieces with tea.']::text[], array['traditional', 'classical']::text[], array['#1e0a23', '#dcc898', '#f0a030']::text[], 22.3, 114.2, 'https://en.wikipedia.org/wiki/Mid-Autumn_Festival', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
