insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('dragon-boat-festival', 'Dragon Boat Festival', 'Duanwu', 'Racing boats and rice parcels', 'Teams race long dragon-headed boats to the beat of a drum, and families eat zongzi wrapped in leaves.', (select id from public.regions where slug = 'east-asia'), 'community', 'Chinese communities, with related early-summer festivals in neighbouring cultures', '{"kind":"table","calendar":"Chinese lunisolar calendar (5th day of the 5th month)","typicalMonths":[5,6]}'::jsonb, 'Falls in late May or June.', 'The festival is popularly linked to the poet Qu Yuan of the Warring States period; other regions tie it to different figures. It was inscribed on UNESCO''s intangible heritage list in 2009.', 'Traditionally a time to ward off illness at the start of summer, and now a celebration of teamwork and community.', array['The customary greeting wishes peace and health rather than happiness.']::text[], array['traditional']::text[], array['#0e5a48', '#fbf6ea', '#b93626']::text[], 28.8, 113.1, 'https://en.wikipedia.org/wiki/Dragon_Boat_Festival', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
