insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('hanami', 'Hanami', null, 'Gathering under the cherry blossom', 'For a short season each spring, friends, families and colleagues picnic beneath flowering cherry trees.', (select id from public.regions where slug = 'east-asia'), 'spring', 'People across Japan', '{"kind":"seasonal","months":[3,4]}'::jsonb, 'There is no fixed date. Blossom moves north through Japan from late March to early May and lasts about a week in each place; forecasts are published each year.', 'Flower viewing began among the Nara and Heian court, first with plum and then cherry blossom, and spread to the wider public in the Edo period.', 'The brief bloom is a reminder that beauty passes quickly, and a reason to stop and spend time together.', array['Do not pick blossom or shake branches.', 'Take all rubbish home and keep to marked picnic areas.']::text[], array['j-pop', 'traditional']::text[], array['#fbf6ea', '#e7a6b8', '#574f5c']::text[], 35.68, 139.69, 'https://en.wikipedia.org/wiki/Hanami', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
