insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('gion-matsuri', 'Gion Matsuri', null, 'Kyoto''s month of floats', 'A month-long festival of Yasaka Shrine, famous for towering wooden floats pulled through the streets of Kyoto.', (select id from public.regions where slug = 'east-asia'), 'faith', 'The neighbourhoods of central Kyoto and Yasaka Shrine', '{"kind":"fixed","month":7,"day":1,"durationDays":31}'::jsonb, 'Runs throughout July. The main float processions are on 17 and 24 July, with street evenings on the three nights before each.', 'It began in 869 as a ritual to appease the spirits believed to cause an epidemic. The float procession is inscribed on UNESCO''s intangible heritage list.', 'Neighbourhood associations have maintained their own floats for centuries, making the festival a living record of the city''s craft and community.', array['Floats are sacred objects; follow instructions about where you may stand or board.']::text[], array['traditional']::text[], array['#241f27', '#b93626', '#dcc898']::text[], 35, 135.77, 'https://en.wikipedia.org/wiki/Gion_Matsuri', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
