insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('songkran', 'Songkran', null, 'Thailand''s water-blessed new year', 'The traditional Thai New Year: temple visits, respect paid to elders, and nationwide water play in the hottest month.', (select id from public.regions where slug = 'southeast-asia'), 'new-year', 'People across Thailand, with sister festivals in Laos, Cambodia and Myanmar', '{"kind":"fixed","month":4,"day":13,"durationDays":3}'::jsonb, '13 to 15 April each year. Some cities extend the celebrations by several days.', 'Songkran marks the sun''s passage into Aries in the traditional calendar. It was inscribed on UNESCO''s intangible heritage list in 2023.', 'Water stands for washing away the old year. The heart of the festival is gratitude towards elders and ancestors.', array['Do not splash monks, elders, or people who are clearly not taking part.', 'Use clean water and keep it away from motorcyclists.']::text[], array['traditional', 'world']::text[], array['#f2e7cf', '#1f7f9c', '#dca92b']::text[], 18.79, 98.98, 'https://en.wikipedia.org/wiki/Songkran_(Thailand)', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
