insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('vesak', 'Vesak', 'Buddha Purnima, Visakha Bucha, Waisak', 'The full moon of the Buddha', 'The most widely observed Buddhist festival, honouring the birth, enlightenment and passing of the Buddha with lanterns, offerings and acts of kindness.', (select id from public.regions where slug = 'south-asia'), 'faith', 'Buddhist communities worldwide', '{"kind":"table","calendar":"Buddhist lunar calendars (full moon of Vesakha)","typicalMonths":[4,5,6]}'::jsonb, 'Usually the full moon of May. Countries set the date by different calendars, so it can vary by days or even a month.', 'Buddhist traditions have honoured this full moon for many centuries. The United Nations recognised the Day of Vesak in 1999.', 'Theravada tradition holds that the Buddha''s birth, enlightenment and final passing all took place on this full moon.', array['Dress modestly, often in white, when visiting temples.', 'It is a day of restraint; alcohol sales are suspended in several countries.']::text[], array['traditional', 'classical']::text[], array['#fbf6ea', '#dca92b', '#574f5c']::text[], 7.29, 80.63, 'https://en.wikipedia.org/wiki/Vesak', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
