insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('nowruz', 'Nowruz', null, 'A new day at the spring equinox', 'The Persian New Year, celebrated for more than three thousand years at the exact moment spring begins.', (select id from public.regions where slug = 'middle-east'), 'new-year', 'Iranian, Afghan, Kurdish, Azerbaijani and Central Asian communities, among others', '{"kind":"table","calendar":"Solar Hijri calendar (March equinox)","typicalMonths":[3]}'::jsonb, 'Begins at the March equinox, on 20 or 21 March depending on the year and time zone. Celebrations continue for thirteen days.', 'Nowruz has roots in ancient Iranian and Zoroastrian tradition. It is on UNESCO''s intangible heritage list, and the UN marks 21 March as the International Day of Nowruz.', 'It celebrates renewal: of nature, of the home, and of relationships, with visits to elders first.', array['Younger people visit their elders first, and visits are returned.']::text[], array['traditional', 'classical']::text[], array['#0e5a48', '#fbf6ea', '#e7a6b8']::text[], 29.59, 52.58, 'https://en.wikipedia.org/wiki/Nowruz', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
