insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('hanukkah', 'Hanukkah', null, 'Eight nights of light', 'A Jewish festival of eight nights, lighting one more candle each evening and sharing fried food, songs and games.', (select id from public.regions where slug = 'middle-east'), 'light', 'Jewish communities worldwide', '{"kind":"table","calendar":"Hebrew calendar (25 Kislev)","typicalMonths":[11,12]}'::jsonb, 'Begins at sunset on the first date shown and lasts eight nights. It falls between late November and late December.', 'Hanukkah commemorates the rededication of the Second Temple in Jerusalem in the second century BCE, after the Maccabean revolt.', 'Tradition tells of a single day''s oil that burned for eight; the festival celebrates perseverance and religious freedom.', array['Candles are lit after nightfall and placed where they can be seen from outside.']::text[], array['traditional', 'folk']::text[], array['#1b2f6b', '#dcc898', '#fbf6ea']::text[], 31.77, 35.21, 'https://en.wikipedia.org/wiki/Hanukkah', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
