insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('christmas', 'Christmas', null, 'A midwinter celebration of birth and giving', 'The Christian celebration of the birth of Jesus, also kept as a cultural holiday of lights, music, food and gifts around the world.', (select id from public.regions where slug = 'europe'), 'faith', 'Christian communities worldwide, and many others as a cultural holiday', '{"kind":"fixed","month":12,"day":25,"durationDays":1}'::jsonb, '25 December in most churches. Many Orthodox churches that follow the Julian calendar celebrate on 7 January.', 'Christmas has been kept on 25 December since at least the fourth century. Many familiar customs, such as the decorated tree, spread widely in the nineteenth century.', 'For Christians it marks the incarnation; more broadly it has become a season of generosity and gathering.', array['Customs differ widely; ask your hosts whether gifts are opened on the 24th or the 25th.']::text[], array['classical', 'jazz', 'folk']::text[], array['#083b30', '#b93626', '#dcc898']::text[], 49.45, 11.08, 'https://en.wikipedia.org/wiki/Christmas', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
