insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('semana-santa', 'Semana Santa', null, 'Holy Week in procession', 'In the week before Easter, brotherhoods carry sculpted floats through the streets of Spanish and Latin American cities.', (select id from public.regions where slug = 'europe'), 'faith', 'Catholic communities in Spain, Latin America and the Philippines', '{"kind":"easter-offset","offsetDays":-7,"durationDays":8}'::jsonb, 'Runs from Palm Sunday to Easter Sunday; calculated from the Western date of Easter.', 'The processions of lay brotherhoods (cofradías) took shape in the sixteenth century and many of the sculptures carried today date from the Baroque period.', 'It is a solemn public meditation on the Passion, and a deep expression of neighbourhood identity.', array['This is a religious observance: keep quiet as floats pass and never cross a procession.', 'The pointed hoods are centuries-old penitential dress.']::text[], array['classical', 'traditional']::text[], array['#33143a', '#dcc898', '#fbf6ea']::text[], 37.39, -5.99, 'https://en.wikipedia.org/wiki/Holy_Week_in_Spain', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
