insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('rio-carnival', 'Carnival in Rio', 'Carnaval', 'Samba before Lent', 'Samba schools parade through the Sambadrome while hundreds of street parties fill the city in the days before Ash Wednesday.', (select id from public.regions where slug = 'latin-america'), 'arts', 'People across Brazil; carnival is also celebrated in many Catholic-heritage countries', '{"kind":"easter-offset","offsetDays":-51,"durationDays":6}'::jsonb, 'From the Friday before Ash Wednesday to Ash Wednesday itself; calculated from the Western date of Easter.', 'Rio''s carnival blends European pre-Lenten festivities with Afro-Brazilian music and dance. Samba schools emerged in the 1920s and have paraded in the Sambadrome since 1984.', 'Each school spends the year building a parade around a chosen theme, making carnival a major community and artistic effort.', array['Street parties are crowded; carry little and agree a meeting point.']::text[], array['latin', 'world']::text[], array['#0e5a48', '#f0a030', '#c2267a']::text[], -22.91, -43.17, 'https://en.wikipedia.org/wiki/Rio_Carnival', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
