insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('dia-de-muertos', 'Día de Muertos', 'Day of the Dead', 'Welcoming loved ones home', 'Mexican families build altars of marigolds, candles and favourite foods to welcome the spirits of their dead for a night.', (select id from public.regions where slug = 'latin-america'), 'remembrance', 'People across Mexico and Mexican communities abroad', '{"kind":"fixed","month":11,"day":1,"durationDays":2}'::jsonb, '1 and 2 November. Preparations and some observances begin in the last days of October.', 'The celebration joins Indigenous traditions of honouring the dead with the Catholic days of All Saints and All Souls. UNESCO recognised it as intangible heritage in 2008.', 'Death is treated as part of life: the dead are remembered with warmth, humour and hospitality rather than fear.', array['It is a family remembrance, not a version of Halloween.', 'Ask before photographing altars or graves.']::text[], array['latin', 'folk', 'traditional']::text[], array['#33143a', '#f0a030', '#c2267a']::text[], 17.07, -96.72, 'https://en.wikipedia.org/wiki/Day_of_the_Dead', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
