insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('oktoberfest', 'Oktoberfest', null, 'Munich''s autumn fair', 'The world''s largest folk festival: brewery tents, brass bands, fairground rides and Bavarian dress on the Theresienwiese.', (select id from public.regions where slug = 'europe'), 'community', 'Munich and Bavaria, with visitors from around the world', '{"kind":"custom","id":"oktoberfest"}'::jsonb, 'Opens on the first Saturday after 15 September and runs to the first Sunday of October, or to 3 October if that is later.', 'It began in October 1810 as the public celebration of the wedding of Crown Prince Ludwig of Bavaria and Princess Therese.', 'It is a showcase of Bavarian brewing, food, music and dress.', array['Tents fill early and seats are needed to be served.', 'Family days offer reduced prices on rides.']::text[], array['folk', 'traditional']::text[], array['#f2e7cf', '#1b4f8a', '#9a5005']::text[], 48.14, 11.58, 'https://en.wikipedia.org/wiki/Oktoberfest', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
