insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('la-tomatina', 'La Tomatina', null, 'One hour of tomatoes in Buñol', 'On the last Wednesday of August, a small Valencian town hosts a good-natured tomato fight lasting exactly one hour.', (select id from public.regions where slug = 'europe'), 'community', 'The town of Buñol and ticketed visitors', '{"kind":"nth-weekday","month":8,"weekday":3,"nth":-1,"durationDays":1}'::jsonb, 'The last Wednesday of August. Entry has been ticketed since 2013.', 'It is said to have started in 1945 with a scuffle during a town parade, and was later adopted as an official festival.', 'It is simply for fun, and part of a week of celebrations for the town''s patron saints.', array['Squash tomatoes before throwing them.', 'Do not bring bottles or hard objects, and stop at the second signal.']::text[], array['latin', 'rock']::text[], array['#b93626', '#fbf6ea', '#0e5a48']::text[], 39.42, -0.79, 'https://en.wikipedia.org/wiki/La_Tomatina', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
