insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('st-patricks-day', 'St Patrick''s Day', 'Lá Fhéile Pádraig', 'Ireland''s national day', 'The feast of Ireland''s patron saint, celebrated with parades, music and green in Ireland and wherever Irish people have settled.', (select id from public.regions where slug = 'europe'), 'community', 'Ireland and the Irish diaspora', '{"kind":"fixed","month":3,"day":17,"durationDays":1}'::jsonb, '17 March each year.', 'The day has been a religious feast for centuries. Large parades grew up among Irish communities abroad, with New York''s dating from the eighteenth century.', 'It honours St Patrick and has become a celebration of Irish culture and identity.', array['In Ireland the short form is ''Paddy''s Day''.']::text[], array['folk', 'traditional', 'rock']::text[], array['#0e5a48', '#fbf6ea', '#f0a030']::text[], 53.35, -6.26, 'https://en.wikipedia.org/wiki/Saint_Patrick%27s_Day', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
