insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('timkat', 'Timkat', null, 'Ethiopia''s Epiphany', 'Ethiopian Orthodox Christians celebrate the baptism of Jesus with overnight vigils, processions and the blessing of water.', (select id from public.regions where slug = 'africa'), 'faith', 'Ethiopian and Eritrean Orthodox Tewahedo Christians', '{"kind":"fixed","month":1,"day":18,"durationDays":3}'::jsonb, 'Ketera, the eve, is 18 January and Timkat itself 19 January; both fall one day later in Gregorian leap years.', 'Timkat is among the oldest and most important festivals of the Ethiopian Orthodox Church. UNESCO inscribed it as intangible heritage in 2019.', 'It re-enacts the baptism in the Jordan, and is a time for the whole community to renew its vows.', array['White traditional dress is customary.', 'The tabot is sacred and always kept covered; give processions space.']::text[], array['traditional', 'world']::text[], array['#fbf6ea', '#0e5a48', '#dca92b']::text[], 12.6, 37.47, 'https://en.wikipedia.org/wiki/Timkat', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
