insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('inti-raymi', 'Inti Raymi', null, 'The Inca festival of the sun', 'On the southern winter solstice, Cusco stages a ceremony in Quechua honouring the sun, in the plazas and fortress the Inca built.', (select id from public.regions where slug = 'latin-america'), 'community', 'Cusco and Andean communities in Peru, Ecuador and Bolivia', '{"kind":"fixed","month":6,"day":24,"durationDays":1}'::jsonb, '24 June each year in Cusco.', 'Inti Raymi was the most important ceremony of the Inca state. Suppressed under Spanish rule in the sixteenth century, it was revived as a staged re-enactment in 1944.', 'It gives thanks to the sun at the turn of the agricultural year and affirms Quechua language and identity.', array['The Sacsayhuamán performance has paid seating; hillsides around it are free and fill early.']::text[], array['traditional', 'folk', 'world']::text[], array['#9a5005', '#f0a030', '#b93626']::text[], -13.53, -71.97, 'https://en.wikipedia.org/wiki/Inti_Raymi', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
