insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('thanksgiving', 'Thanksgiving', null, 'A shared harvest table', 'A national holiday in the United States centred on a large family meal and giving thanks.', (select id from public.regions where slug = 'north-america'), 'harvest', 'People across the United States; Canada has its own Thanksgiving in October', '{"kind":"nth-weekday","month":11,"weekday":4,"nth":4,"durationDays":1}'::jsonb, 'The fourth Thursday of November in the United States. Canadian Thanksgiving is the second Monday of October.', 'The holiday is traditionally traced to a 1621 harvest meal shared by English colonists and Wampanoag people at Plymouth. Abraham Lincoln proclaimed a national day in 1863, and the date was fixed in 1941.', 'For most families it is the main gathering of the year. Many Native Americans observe the day as a National Day of Mourning, held at Plymouth since 1970.', array['Guests usually bring a dish; ask your host what is needed.']::text[], array['folk', 'jazz', 'blues']::text[], array['#f2e7cf', '#9a5005', '#0e5a48']::text[], 41.96, -70.67, 'https://en.wikipedia.org/wiki/Thanksgiving_(United_States)', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
