insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('midsummer', 'Midsummer', 'Midsommar', 'Sweden''s longest days', 'Swedes head to the countryside to raise a leaf-covered pole, dance around it, and eat herring, new potatoes and strawberries.', (select id from public.regions where slug = 'europe'), 'community', 'People across Sweden, with related midsummer festivals around the Baltic and Nordic countries', '{"kind":"custom","id":"midsummer-sweden"}'::jsonb, 'Midsummer Eve is the Friday between 19 and 25 June, followed by Midsummer Day.', 'Midsummer celebrations in the Nordic countries are far older than their written records; the pole and its dances were established by the early modern period.', 'After a long winter, it is the celebration of light, greenery and being outdoors.', array['Everyone joins the dancing, however silly it feels.']::text[], array['folk', 'traditional', 'indie']::text[], array['#fbf6ea', '#1b4f8a', '#dca92b']::text[], 60.73, 15, 'https://en.wikipedia.org/wiki/Midsummer', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
