insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('naadam', 'Naadam', null, 'Mongolia''s three games', 'A national festival of wrestling, horse racing and archery held each July across Mongolia.', (select id from public.regions where slug = 'central-asia'), 'community', 'People across Mongolia, and Mongol communities elsewhere', '{"kind":"fixed","month":7,"day":11,"durationDays":3}'::jsonb, 'The national Naadam is held from 11 to 13 July in Ulaanbaatar. Provinces and districts hold their own on nearby dates.', 'The games grew out of the skills of nomadic life and military training. Naadam was inscribed on UNESCO''s intangible heritage list in 2010.', 'It celebrates national independence and the nomadic heritage of the steppe.', array['Dust from a winning horse is considered lucky; stand back as the riders arrive.']::text[], array['traditional', 'world']::text[], array['#1b4f8a', '#fbf6ea', '#b93626']::text[], 47.89, 106.91, 'https://en.wikipedia.org/wiki/Naadam', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
