insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('matariki', 'Matariki', null, 'The Māori New Year', 'The midwinter rising of the Matariki star cluster marks the Māori New Year, a time to remember, give thanks and plan ahead.', (select id from public.regions where slug = 'oceania'), 'new-year', 'Māori, and all of Aotearoa New Zealand as a public holiday', '{"kind":"table","calendar":"Maramataka, the Māori lunar calendar","typicalMonths":[6,7]}'::jsonb, 'The public holiday falls on a Friday in June or July, set from the Māori lunar calendar. Iwi observe the season over several days.', 'Observing Matariki, the cluster also known as the Pleiades, is a long-standing Māori practice that was widely revived from the 1990s. It has been a public holiday since 2022.', 'It is a time to honour those who have died in the past year, celebrate the present with food and company, and set intentions for the year ahead.', array['Follow the lead of local iwi at any ceremony you are invited to.']::text[], array['traditional', 'world', 'indie']::text[], array['#1e0a23', '#dcc898', '#1f7f9c']::text[], -41.29, 174.78, 'https://en.wikipedia.org/wiki/Matariki', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
