insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('meskel', 'Meskel', null, 'The finding of the True Cross, lit by a bonfire', 'Ethiopian and Eritrean Orthodox Christians mark the finding of the True Cross with processions, song and the great Demera bonfire.', (select id from public.regions where slug = 'africa'), 'faith', 'Ethiopian and Eritrean Orthodox Tewahedo Christians, and Ethiopians of many backgrounds', '{"kind":"table","calendar":"Ethiopian calendar (17 Meskerem)","typicalMonths":[9]}'::jsonb, 'Meskel falls on 17 Meskerem in the Ethiopian calendar: 27 September, or 28 September in Ethiopian leap years. The Demera bonfire is lit on the eve.', 'The feast commemorates Empress Helena''s finding of the cross in the fourth century, a tradition kept in Ethiopia for well over a thousand years. UNESCO inscribed Meskel on its Representative List of the Intangible Cultural Heritage of Humanity in 2013.', 'For the faithful it honours the cross of Christ; it also marks the end of the rainy season and is a time to return to family villages.', array['Dress modestly for church processions, and ask before photographing priests or worshippers.', 'Keep a safe distance from the bonfire; crowds are large.']::text[], array['traditional', 'world']::text[], array['#f0a030', '#1e0a23', '#e8d36a']::text[], 9.01, 38.76, 'https://en.wikipedia.org/wiki/Meskel', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, 