insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('homowo', 'Homowo', null, 'Hooting at hunger after a famine long ago', 'The Ga people of Greater Accra celebrate the harvest and remember a famine their ancestors survived, with kpokpoi, drumming and homecoming.', (select id from public.regions where slug = 'africa'), 'harvest', 'Ga communities of the Greater Accra Region and the Ga diaspora', '{"kind":"seasonal","months":[8]}'::jsonb, 'Each Ga traditional area sets its own dates, mostly in August, after sowing in May and a month-long ban on drumming and noise.', 'Ga oral history tells of a famine during their migration to the coast; when the rains returned and crops grew, the people celebrated by ''hooting at hunger'', the meaning of Homowo.', 'It is thanksgiving for the harvest, remembrance of ancestors and a homecoming that renews family ties.', array['Respect the ban on drumming and noise while it is in force.', 'Follow local guidance at ceremonies, and ask before photographing rituals.']::text[], array['traditional', 'afrobeats']::text[], array['#b93626', '#fbf6ea', '#0e5a48']::text[], 5.54, -0.21, 'https://en.wikipedia.org/wiki/Homowo', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
