insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('vodun-days', 'Vodun Days', 'Fête du Vodoun', 'Benin honours its traditional religion on the Atlantic coast', 'Ouidah hosts a public celebration of Vodun, the traditional religion of the Fon, Ewe and neighbouring peoples, around Benin''s national day for traditional religions.', (select id from public.regions where slug = 'africa'), 'faith', 'Vodun adherents in Benin, Togo and the diaspora, with visitors from many countries', '{"kind":"table","calendar":"Set by the Government of Benin","typicalMonths":[1]}'::jsonb, 'Benin marked traditional religions on 10 January from 1996; from 2027 the national day falls on the second Friday of January, with Vodun Days around it.', 'Vodun has been practised in the region for centuries and travelled across the Atlantic with enslaved people. Benin recognised it with a national holiday in 1996, and the government began organising Vodun Days in Ouidah in 2024.', 'It honours the vodun (spirits) and ancestors, and affirms a religion long stigmatised by outsiders as part of Benin''s identity.', array['Ask before photographing ceremonies or adepts; some rites are closed to outsiders.', 'Do not touch masquerades or ritual objects.']::text[], array['traditional', 'afrobeats']::text[], array['#fbf6ea', '#33143a', '#c28b2c']::text[], 6.36, 2.09, 'https://en.wikipedia.org/wiki/West_African_Vodun', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
