insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('tweede-nuwe-jaar', 'Tweede Nuwe Jaar', 'Kaapse Klopse', 'Cape Town''s Second New Year street carnival', 'Minstrel troupes in satin suits parade through Cape Town on 2 January to ghoema drums and banjos, a tradition rooted in the city''s history of slavery.', (select id from public.regions where slug = 'africa'), 'arts', 'Cape Coloured and Cape Malay communities of Cape Town', '{"kind":"fixed","month":1,"day":2,"durationDays":1}'::jsonb, 'The street parade is on 2 January; troupe competitions continue at stadiums over the following weeks.', 'Enslaved people at the Cape were traditionally allowed 2 January as their one day off, and celebrated it with music and processions. After emancipation the day grew into the minstrel carnival, with organised troupes recorded from the late 19th century.', 'For many Capetonians it is ''our day'': a celebration of creole culture, music and survival.', array['The carnival''s name and its history of face paint are debated; the official name is the Cape Town Minstrel Carnival.', 'Watch from the pavement and give troupes room to pass.']::text[], array['jazz', 'traditional']::text[], array['#f0a030', '#1f7f9c', '#b93626']::text[], -33.92, 18.42, 'https://en.wikipedia.org/wiki/Kaapse_Klopse', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
