insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('loy-krathong', 'Loy Krathong', null, 'Floating candlelit baskets on the November full moon', 'Across Thailand people float krathong, small rafts of banana leaf, flowers and candles, on rivers and ponds to give thanks to water and let go of misfortune.', (select id from public.regions where slug = 'southeast-asia'), 'light', 'People across Thailand, with related festivals in Laos, Myanmar and Cambodia', '{"kind":"table","calendar":"Thai lunar calendar (full moon of the twelfth month)","typicalMonths":[10,11]}'::jsonb, 'Held on the full moon of the twelfth month of the Thai lunar calendar, usually in November. Chiang Mai''s Yi Peng lantern festival falls at the same time.', 'The festival has been celebrated for centuries and is associated in popular tradition with the Sukhothai kingdom; its origins mix Brahmanical and Buddhist practice.', 'It thanks Phra Mae Khongkha, the water goddess, and asks forgiveness for polluting water; floating the krathong is also a way of letting go of bad luck.', array['Choose a krathong made of natural, biodegradable materials.', 'Release sky lanterns only where permitted; many areas restrict them.']::text[], array['traditional', 'world']::text[], array['#1e0a23', '#f0a030', '#7fb685']::text[], 17.01, 99.82, 'https://en.wikipedia.org/wiki/Loi_Krathong', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = ex