insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('sinulog', 'Sinulog', 'Sinulog-Santo Niño Festival', 'Cebu dances for the Holy Child', 'Cebu City honours the Santo Niño, the image of the Child Jesus, with novena Masses, a river procession and a grand parade of street dancers.', (select id from public.regions where slug = 'southeast-asia'), 'faith', 'Catholics in Cebu and across the Philippines, and visitors', '{"kind":"nth-weekday","month":1,"weekday":0,"nth":3,"durationDays":1}'::jsonb, 'The grand parade is on the third Sunday of January, after nine days of novena Masses.', 'The Santo Niño image was given in Cebu in 1521 during Magellan''s expedition. The Sinulog prayer-dance has older, pre-Hispanic roots; the modern festival parade began in 1980.', 'It is an act of devotion to the Santo Niño and a remembrance of the arrival of Christianity in the Philippines.', array['Masses are acts of worship: dress respectfully and keep quiet inside.', 'Crowds are very large; agree a meeting point with your group.']::text[], array['traditional', 'world']::text[], array['#b93626', '#f0a030', '#33143a']::text[], 10.29, 123.9, 'https://en.wikipedia.org/wiki/Sinulog', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
