insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('thaipusam', 'Thaipusam', null, 'Vows to Lord Murugan, carried up the steps', 'Tamil Hindus honour Lord Murugan with fasting, prayer and pilgrimages, many carrying milk pots or kavadi as fulfilment of vows.', (select id from public.regions where slug = 'southeast-asia'), 'faith', 'Tamil Hindu communities, especially in Malaysia, Singapore, India and Mauritius', '{"kind":"table","calendar":"Tamil calendar (the month of Thai, Poosam star)","typicalMonths":[1,2]}'::jsonb, 'Falls in the Tamil month of Thai, when the Poosam star coincides with the full moon, between mid-January and mid-February.', 'Thaipusam commemorates the day the goddess Parvati gave Murugan the vel, the spear with which he defeated the demon Soorapadman. It travelled with Tamil communities to Southeast Asia; the Batu Caves pilgrimage in Malaysia dates from the late 19th century.', 'Devotees seek blessings, give thanks for prayers answered, and fulfil vows through penance and devotion.', array['Dress modestly and remove shoes where asked.', 'Do not obstruct devotees carrying kavadi, and ask before photographing them.']::text[], array['traditional', 'classical']::text[], array['#f0a030', '#0e5a48', '#33143a']::text[], 3.24, 101.68, 'https://en.wikipedia.org/wiki/Thaipusam', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude,