insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('garma', 'Garma Festival', null, 'Yolŋu culture shared on Gumatj Country', 'Australia''s largest Indigenous cultural gathering: four days of Yolŋu ceremony, dance, music, art and national conversation at Gulkula in north-east Arnhem Land.', (select id from public.regions where slug = 'oceania'), 'arts', 'Yolŋu clans of north-east Arnhem Land, hosting visitors from across Australia and abroad', '{"kind":"seasonal","months":[7,8]}'::jsonb, 'The Yothu Yindi Foundation sets the dates each year, usually four days around the start of August. 2026 ran from 31 July to 3 August.', 'Garma was founded in 1999 by Yolŋu leaders including Dr Galarrwuy Yunupingu and Dr M. Yunupingu of the band Yothu Yindi, and is hosted at Gulkula, a Gumatj ceremonial ground.', 'In Yolŋu Matha ''garma'' refers to a two-way learning process; the festival keeps culture strong and is a forum for Indigenous voices in national life.', array['Attendance is by registration with the Yothu Yindi Foundation; follow its cultural protocols.', 'Follow guidance on photography and on naming people who have died.']::text[], array['traditional', 'world']::text[], array['#b93626', '#e8d36a', '#1e0a23']::text[], -12.28, 136.82, 'https://en.wikipedia.org/wiki/Garma_Festival_of_Traditional_Cultures', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
