insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('merrie-monarch', 'Merrie Monarch Festival', null, 'The week of hula in Hilo', 'A week-long festival of Hawaiian culture in Hilo, ending in three nights of the world''s most prestigious hula competition.', (select id from public.regions where slug = 'oceania'), 'arts', 'Native Hawaiian hālau hula (hula schools) and the people of Hawaiʻi', '{"kind":"easter-offset","offsetDays":0,"durationDays":7}'::jsonb, 'Begins on Easter Sunday and runs through the following Saturday; the competition is Thursday to Saturday.', 'Founded in Hilo in the 1960s to honour King David Kalākaua, the ''Merrie Monarch'' who revived hula in the 19th century. The hula competition was added in 1971, and men''s hālau joined in 1976.', 'It celebrates and passes on hula, chant and Hawaiian language, and is a pillar of the Hawaiian cultural renaissance.', array['Competition tickets are limited; the event is also broadcast and streamed.', 'Hula is sacred practice as well as performance: watch respectfully.']::text[], array['traditional', 'world']::text[], array['#0e5a48', '#f0a030', '#b93626']::text[], 19.72, -155.08, 'https://en.wikipedia.org/wiki/Merrie_Monarch_Festival', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
