insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('sami-national-day', 'Sámi National Day', null, 'The national day of a people across four countries', 'On 6 February the Sámi of Norway, Sweden, Finland and Russia raise their flag, wear gákti and gather for concerts, food and culture.', (select id from public.regions where slug = 'europe'), 'community', 'Sámi people across Sápmi, and many public institutions in the Nordic countries', '{"kind":"fixed","month":2,"day":6,"durationDays":1}'::jsonb, 'Always 6 February.', 'The date marks the first Sámi congress, held in Trondheim on 6 February 1917, when Sámi from Norway and Sweden first met across borders. The day was adopted at the Sámi Conference in Helsinki in 1992 and first celebrated in 1993.', 'It celebrates Sámi unity and identity across national borders, and the long struggle for Sámi rights.', array['Do not wear gákti as a costume if you are not Sámi.', 'Ask before photographing people in traditional dress.']::text[], array['folk', 'traditional']::text[], array['#c8102e', '#0033a0', '#ffcd00']::text[], 69.47, 25.51, 'https://en.wikipedia.org/wiki/Sámi_National_Day', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
