insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('candelaria-puno', 'Virgen de la Candelaria', 'Fiesta de la Candelaria', 'Puno''s patron honoured with thousands of dancers', 'In February the city of Puno on Lake Titicaca honours its patron, the Virgin of Candelaria, with Masses, processions and some of the largest dance competitions in the Andes.', (select id from public.regions where slug = 'latin-america'), 'faith', 'The people of Puno and the Quechua and Aymara communities of the region', '{"kind":"fixed","month":2,"day":2,"durationDays":1}'::jsonb, 'The central day is 2 February, Candlemas. The festivity lasts about two weeks, with the octave processions and dance contests on dates set each year.', 'Devotion to the Virgin of Candelaria came with Spanish Catholicism and merged with Andean traditions of the Altiplano. UNESCO inscribed the festivity on its Representative List of the Intangible Cultural Heritage of Humanity in 2014.', 'It is devotion to the Virgin joined with Andean reverence for Pachamama, the earth, and a showcase of the region''s music and dance.', array['Puno is at about 3,800 metres: allow time to acclimatise.', 'Processions are religious: keep the route clear and dress warmly and respectfully.']::text[], array['traditional', 'latin']::text[], array['#f0a030', '#1f7f9c', '#b93626']::text[], -15.84, -70.02, 'https://en.wikipedia.org/wiki/Fiesta_de_la_Candelaria', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = ex