insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('guelaguetza', 'Guelaguetza', 'Lunes del Cerro', 'Oaxaca''s regions dance and share their gifts', 'On two Mondays in July, delegations from Oaxaca''s eight regions perform their dances, music and dress on the Cerro del Fortín, and give gifts to the audience.', (select id from public.regions where slug = 'latin-america'), 'arts', 'The Indigenous and Afro-Mexican peoples of Oaxaca and the whole state', '{"kind":"table","calendar":"The two Mondays after 16 July (Lunes del Cerro)","typicalMonths":[7]}'::jsonb, 'The two Lunes del Cerro (Mondays on the Hill) follow 16 July; events fill the whole month.', 'The celebration links pre-Hispanic festivities on the Cerro del Fortín with the colonial feast of the Virgen del Carmen. The present open-air auditorium on the hill was built in the 1970s.', '''Guelaguetza'' is a Zapotec idea of reciprocity: giving and receiving among communities.', array['Seats in the auditorium''s upper sections are free but fill early.', 'Each dress and dance belongs to a particular community: describe it by its place, not as a generic costume.']::text[], array['traditional', 'latin']::text[], array['#b93626', '#f0a030', '#0e5a48']::text[], 17.07, -96.72, 'https://en.wikipedia.org/wiki/Guelaguetza', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.lo