insert into public.festival_dates (festival_id, starts_on, ends_on, status, note, source_url, last_checked_at) values ((select id from public.festivals where slug = 'guelaguetza'), '2027-07-19', '2027-07-26', 'projected', 'The Lunes del Cerro fall on the two Mondays after 16 July (21 and 28 July in 2025, 20 and 27 July in 2026). That gives 19 and 26 July 2027; the state government announces the official dates.', 'https://www.nmas.com.mx/cultura/guelaguetza-2026-en-vivo-donde-ver-transmision-actividades-por-dia-20-27-julio-cuanto-dura/', '2026-11-16T00:00:00Z'::timestamptz) on conflict (festival_id, starts_on) do update set ends_on = excluded.ends_on, status = excluded.status, note = excluded.note, source_url = excluded.source_url, last_checked_at = excluded.last_checked_at;
insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('junkanoo', 'Junkanoo', null, 'The Bahamas rushes through the night', 'On Boxing Day and New Year''s Day, Junkanoo groups ''rush'' along Bay Street in Nassau before dawn in crêpe-paper costumes, to goatskin drums, cowbells and horns.', (select id from public.regions where slug = 'latin-america'), 'arts', 'People across The Bahamas and the Bahamian diaspora', '{"kind":"fixed","month":12,"day":26,"durationDays":7}'::jsonb, 'The parades are on 26 December (Boxing Day) and 1 January, in the early hours, roughly 1 a.m. to 9 a.m. FESTIVA shows the week between them.', 'Junkanoo grew from the days off that enslaved people were given at Christmas, and its exact origins are debated. After emancipation it became an organised, judged parade.', 'It is a celebration of Bahamian identity, freedom and creativity, built by groups over months.', array['Arrive early for a place on the route; grandstand seats are ticketed.', 'Do not step into the parade route.']::text[], array['traditional', 'world']::text[], array['#00abc9', '#ffc72c', '#1e0a23']::text[], 25.08, -77.34, 'https://en.wikipedia.org/wiki/Junkanoo', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
