insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('trinidad-carnival', 'Trinidad and Tobago Carnival', null, 'Two days of mas before Ash Wednesday', 'From pre-dawn J''ouvert on Monday to the parade of the bands on Tuesday, Trinidad and Tobago''s Carnival fills the streets with masquerade, soca and steelpan.', (select id from public.regions where slug = 'latin-america'), 'arts', 'People across Trinidad and Tobago, and Caribbean carnivals worldwide that follow its model', '{"kind":"easter-offset","offsetDays":-48,"durationDays":2}'::jsonb, 'Carnival Monday and Tuesday are the two days before Ash Wednesday; the season of fêtes, Panorama and calypso competitions starts after Christmas.', 'Carnival arrived with French Catholic planters in the late 18th century. After emancipation in 1834 freed Africans made it their own, with Canboulay processions remembered today in J''ouvert. Steelpan was invented on the island in the 20th century.', 'It is a celebration of freedom, satire and creativity, and the source of calypso, soca and steelpan.', array['Ask before joining a band: most are paid registrations with costumes.', 'J''ouvert paint gets everywhere: wear old clothes.']::text[], array['world', 'traditional']::text[], array['#ce1126', '#1e0a23', '#f0a030']::text[], 10.65, -61.51, 'https://en.wikipedia.org/wiki/Trinidad_and_Tobago_Carnival', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
