insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('kandy-esala-perahera', 'Kandy Esala Perahera', 'Dalada Perahera', 'The festival of the Sacred Tooth Relic', 'For ten nights in July or August, processions of dancers, drummers, torch-bearers and elephants wind through Kandy in honour of the Sacred Tooth Relic of the Buddha.', (select id from public.regions where slug = 'south-asia'), 'faith', 'Buddhists of Sri Lanka, with the shrines of the four guardian deities of Kandy', '{"kind":"seasonal","months":[7,8]}'::jsonb, 'Held in the Sinhala month of Esala, ending on the full-moon poya day in July or August. The Temple of the Tooth sets the dates each year.', 'Processions of the Tooth Relic go back more than 1,500 years in Sri Lanka; the present Perahera took shape under the Kandyan kings, combining the Dalada (Tooth) procession with those of the four devales.', 'It honours the Tooth Relic, long a symbol of sovereignty in Sri Lanka, and asks blessings for rain and harvest.', array['Seats along the route are sold and crowds are dense; arrive early.', 'Do not use flash near the elephants, and stand respectfully as the relic casket passes.']::text[], array['traditional', 'classical']::text[], array['#f0a030', '#7a1f1f', '#fbf6ea']::text[], 7.29, 80.64, 'https://en.wikipedia.org/wiki/Kandy_Esala_Perahera', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
