insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('makar-sankranti', 'Makar Sankranti', 'Uttarayan', 'The festival of kites and sesame sweets', 'A winter harvest festival marking the sun''s move into Capricorn, celebrated with kites filling the sky, sesame and jaggery sweets, and holy dips in rivers.', (select id from public.regions where slug = 'south-asia'), 'harvest', 'Hindu communities across India and Nepal, under many regional names', '{"kind":"table","calendar":"Hindu solar calendar (sun''s entry into Makara, Capricorn)","typicalMonths":[1]}'::jsonb, 'One of the few Hindu festivals set by the solar calendar, so it falls on 14 or 15 January almost every year.', 'The festival marks the sun''s transit into Makara (Capricorn) and the start of its northward journey, Uttarayana, long held to be an auspicious time in Hindu tradition. It grew into a harvest festival as the winter crops came in.', 'It celebrates longer days, a fresh harvest and generosity: sesame and jaggery, warming foods for winter, are shared with the words ''eat sweet, speak sweet''.', array['Use cotton kite string rather than glass-coated manja, which injures birds and people.', 'Watch out for children on rooftops.', 'Accept sweets with both hands and return the greeting.']::text[], array['folk', 'bollywood']::text[], array['#fbf6ea', '#e8572a', '#2a7fd1']::text[], 23.02, 72.57, 'https://en.wikipedia.org/wiki/Makar_Sankranti', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
