insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('lohri', 'Lohri', null, 'The bonfire festival of Punjab', 'A Punjabi midwinter festival where families gather round a bonfire, throw in sesame, peanuts and popcorn, and sing and dance to celebrate the end of winter and the coming harvest.', (select id from public.regions where slug = 'south-asia'), 'harvest', 'Punjabi communities of all faiths, in India and the diaspora', '{"kind":"fixed","month":1,"day":13,"durationDays":1}'::jsonb, 'Held on the night before Makar Sankranti, usually 13 January (occasionally the 14th).', 'Lohri marks the end of the coldest part of winter in Punjab and the ripening of the rabi crop. Its songs remember Dulla Bhatti, a Robin Hood-like folk hero of the Mughal era who rescued girls and arranged their marriages.', 'It is a festival of warmth and new beginnings: a family''s first Lohri after a wedding or the birth of a child is celebrated with special joy.', array['Walk round the fire clockwise if you join the parikrama.', 'Keep a safe distance and keep children close.', 'Congratulate families celebrating their first Lohri.']::text[], array['folk', 'bollywood']::text[], array['#1e0a23', '#f07a1a', '#f2c14e']::text[], 31.63, 74.87, 'https://en.wikipedia.org/wiki/Lohri', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
