insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('vasant-panchami', 'Vasant Panchami', 'Saraswati Puja', 'The first day of spring, in yellow', 'A spring festival devoted to Saraswati, goddess of knowledge, music and the arts, when people wear yellow, honour books and instruments, and children write their first letters.', (select id from public.regions where slug = 'south-asia'), 'spring', 'Hindu communities, students and artists, especially in eastern and northern India', '{"kind":"table","calendar":"Hindu lunisolar calendar (fifth day of the bright half of Magha)","typicalMonths":[1,2]}'::jsonb, 'Falls on the fifth lunar day of Magha, in late January or February.', 'Vasant Panchami has long marked the start of spring, when mustard fields turn yellow across the northern plains. It became the main day of worship for Saraswati, especially in Bengal, Bihar and Odisha.', 'It celebrates learning and creativity: students place books and pens before the goddess, and many families begin a child''s education on this day.', array['Don''t step over books; they are treated with respect today.', 'Students traditionally rest from study for the day.', 'Wear something yellow if you are invited to a puja.']::text[], array['classical', 'folk']::text[], array['#fbf6ea', '#f2c014', '#e07a1f']::text[], 22.57, 88.36, 'https://en.wikipedia.org/wiki/Vasant_Panchami', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
