insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('maha-shivaratri', 'Maha Shivaratri', null, 'The great night of Shiva', 'A night of fasting, prayer and vigil in honour of Shiva, when temples stay open until dawn and devotees bathe the lingam in milk, water and bel leaves.', (select id from public.regions where slug = 'south-asia'), 'faith', 'Hindus, especially Shaivite communities, in India, Nepal and the diaspora', '{"kind":"table","calendar":"Hindu lunisolar calendar (14th night of the dark half of Phalguna or Magha)","typicalMonths":[2,3]}'::jsonb, 'Falls on the night before the new moon in late February or early March.', 'Shivaratri is mentioned in several Puranas. Stories tie it to the night Shiva performed the cosmic dance, to his marriage to Parvati, and to his drinking the poison churned from the ocean to save the world.', 'It is a night for self-discipline and reflection: staying awake is a way of overcoming darkness and ignorance.', array['Dress modestly and remove shoes at temples.', 'Queues are long: be patient and follow the temple''s arrangements.', 'Ask before photographing sadhus or worshippers.']::text[], array['classical', 'traditional']::text[], array['#14122a', '#5b7fd6', '#e9e4d4']::text[], 25.31, 83.01, 'https://en.wikipedia.org/wiki/Maha_Shivaratri', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude =