insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('ugadi-gudi-padwa', 'Ugadi and Gudi Padwa', null, 'New Year of the Deccan', 'The lunisolar New Year in Karnataka, Andhra Pradesh, Telangana and Maharashtra, welcomed with mango-leaf garlands, a dish of six tastes, and a gudi flag raised outside homes.', (select id from public.regions where slug = 'south-asia'), 'new-year', 'Telugu, Kannada, Marathi and Konkani communities, in India and the diaspora', '{"kind":"table","calendar":"Hindu lunisolar calendar (first day of Chaitra)","typicalMonths":[3,4]}'::jsonb, 'The first day of the bright half of Chaitra, in March or April. Sindhis celebrate Cheti Chand on the same day.', 'Ugadi, from the Sanskrit ''yuga adi'' or beginning of an age, follows the lunisolar calendar used across the Deccan. Gudi Padwa in Maharashtra is linked with Rama''s return to Ayodhya and with the victory flags of the Maratha armies.', 'It is a day for fresh starts: homes are cleaned, new clothes worn, and the year''s almanac read aloud.', array['Taste the ugadi pachadi even if it''s bitter: that is the point.', 'Wish elders first and touch their feet if it''s the family custom.', 'Wear new or freshly washed clothes.']::text[], array['classical', 'folk']::text[], array['#fbf6ea', '#2e8b3a', '#e8a21d']::text[], 17.39, 78.49, 'https://en.wikipedia.org/wiki/Ugadi', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
