insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('vaisakhi', 'Vaisakhi', 'Baisakhi', 'Harvest, and the birth of the Khalsa', 'Punjab''s spring harvest festival and the Sikh New Year, which marks the founding of the Khalsa in 1699, celebrated with processions, langar, bhangra and fairs.', (select id from public.regions where slug = 'south-asia'), 'harvest', 'Sikhs worldwide, and Punjabi farming communities of all faiths', '{"kind":"table","calendar":"Solar calendar (first day of Vaisakh)","typicalMonths":[4]}'::jsonb, 'Set by the solar calendar, so it falls on 13 or 14 April.', 'Vaisakhi was long the harvest festival of Punjab. In 1699, Guru Gobind Singh chose this day at Anandpur Sahib to found the Khalsa, initiating the Panj Pyare, the five beloved ones.', 'For Sikhs it celebrates the Khalsa''s commitment to faith, equality and service; for farmers it gives thanks for the wheat harvest.', array['Cover your head and remove shoes in the gurdwara.', 'Sit on the floor for langar and accept what you are served.', 'Don''t smoke or drink near the procession.']::text[], array['folk', 'traditional']::text[], array['#fbf6ea', '#f28c1e', '#1f3c88']::text[], 31.62, 74.88, 'https://en.wikipedia.org/wiki/Vaisakhi', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_statu