insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('vishu', 'Vishu', null, 'Kerala''s new year at first light', 'The Malayali New Year, which begins with the Vishukkani, an arrangement of golden flowers, fruit, rice and a lamp that is the first thing seen at dawn.', (select id from public.regions where slug = 'south-asia'), 'new-year', 'Malayali communities in Kerala and around the world', '{"kind":"table","calendar":"Solar calendar (first day of Medam)","typicalMonths":[4]}'::jsonb, 'Falls on 14 or 15 April, set by the sun''s entry into Medam (Aries).', 'Vishu marks the astronomical new year in the Malayalam solar calendar. The Vishukkani tradition reflects the belief that what you see first on the new year shapes the year ahead.', 'It celebrates prosperity and hope: the golden konna flowers stand for wealth and the coming monsoon harvest.', array['Keep your eyes closed until you are led to the Vishukkani.', 'Accept kaineetam from elders with both hands.', 'Eat the sadya with your right hand, from a banana leaf.']::text[], array['folk', 'classical']::text[], array['#fbf6ea', '#f2c014', '#2e7d32']::text[], 9.97, 76.28, 'https://en.wikipedia.org/wiki/Vishu', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
