insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('bihu', 'Rongali Bihu', 'Bohag Bihu', 'Assam''s spring new year', 'The Assamese New Year and spring festival, celebrated with Bihu dance and songs, the gift of the woven gamosa, and rice cakes called pitha.', (select id from public.regions where slug = 'south-asia'), 'new-year', 'Assamese people of all communities, in Assam and the diaspora', '{"kind":"table","calendar":"Solar calendar (first days of Bohag)","typicalMonths":[4]}'::jsonb, 'Begins in mid-April with the Assamese month of Bohag; festivities last about a week.', 'Bihu has its roots in the agricultural year of the Brahmaputra valley. Rongali Bihu in spring is the most joyful of three Bihus; the others are Kati Bihu in autumn and Magh Bihu at the winter harvest.', 'It welcomes spring and the sowing season, and celebrates youth, love and Assamese identity.', array['Accept a gamosa with both hands; it is a mark of respect.', 'Ask before joining a dance circle.', 'Elders are greeted first.']::text[], array['folk', 'traditional']::text[], array['#fbf6ea', '#c62828', '#2e7d32']::text[], 26.14, 91.74, 'https://en.wikipedia.org/wiki/Bihu', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
