insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('ram-navami', 'Ram Navami', null, 'The birthday of Rama', 'A spring festival celebrating the birth of Rama, the hero of the Ramayana, with temple worship at noon, readings of the epic, processions and cooling drinks.', (select id from public.regions where slug = 'south-asia'), 'faith', 'Hindus in India, Nepal and the diaspora', '{"kind":"table","calendar":"Hindu lunisolar calendar (ninth day of the bright half of Chaitra)","typicalMonths":[3,4]}'::jsonb, 'The ninth day of Chaitra, in March or April, ending the spring Navratri.', 'The Ramayana tells of Rama''s birth in Ayodhya to King Dasharatha and Queen Kaushalya. The day has been celebrated for centuries, and devotional poets such as Tulsidas popularised its observance.', 'It honours Rama as the ideal of righteousness (dharma), duty and compassion.', array['Remove shoes and dress modestly at temples.', 'Processions can be large: keep to the side and follow local arrangements.', 'Offer prasad back with thanks.']::text[], array['classical', 'traditional']::text[], array['#fbf6ea', '#f28c1e', '#2a5aa8']::text[], 26.8, 82.2, 'https://en.wikipedia.org/wiki/Rama_Navami', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
