insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('rath-yatra', 'Rath Yatra', null, 'The chariot festival of Puri', 'Three towering wooden chariots carrying Jagannath, Balabhadra and Subhadra are pulled through Puri by vast crowds, one of the oldest and largest processions in the world.', (select id from public.regions where slug = 'south-asia'), 'faith', 'Hindus, especially devotees of Jagannath in Odisha, and ISKCON communities worldwide', '{"kind":"table","calendar":"Hindu lunisolar calendar (second day of the bright half of Ashadha)","typicalMonths":[6,7]}'::jsonb, 'Held in June or July, on the second day of the bright half of Ashadha.', 'The festival at Puri has been described for centuries; new chariots are built every year from wood following ancient specifications. The deities travel from the Jagannath Temple to Gundicha Temple and back.', 'It brings the deities out among everyone, regardless of caste or creed: before the chariots move, the Gajapati king sweeps the chariot floors, a symbol that all are equal before God.', array['The crowds are enormous: stay hydrated and keep children close.', 'Only Hindus may enter the Jagannath Temple in Puri.', 'Follow instructions from volunteers and police.']::text[], array['traditional', 'classical']::text[], array['#fbf6ea', '#c62828', '#f2c014']::text[], 19.81, 85.83, 'https://en.wikipedia.org/wiki/Ratha_Yatra_(Puri)', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, 