insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('raksha-bandhan', 'Raksha Bandhan', null, 'A thread between siblings', 'A celebration of the bond between brothers and sisters: a sister ties a rakhi thread on her brother''s wrist, and he promises to look out for her, with gifts and sweets exchanged.', (select id from public.regions where slug = 'south-asia'), 'community', 'Hindus, and many Sikhs, Jains and others in India, Nepal and the diaspora', '{"kind":"table","calendar":"Hindu lunisolar calendar (full moon of Shravana)","typicalMonths":[8]}'::jsonb, 'The full moon of Shravana, in August.', 'Tying protective threads is an old Hindu custom. Popular stories link the festival to Draupadi binding Krishna''s wounded finger, and to Rani Karnavati sending a rakhi to the Mughal emperor Humayun.', 'It celebrates care and responsibility between siblings, and today is widely observed between sisters, cousins and close friends too.', array['Wait for the aarti and tilak before tying the rakhi.', 'Choose a gift your sibling will genuinely use.', 'Siblings who live apart often video-call for the ceremony.']::text[], array['bollywood']::text[], array['#fbf6ea', '#d81b60', '#f2c014']::text[], 28.61, 77.21, 'https://en.wikipedia.org/wiki/Raksha_Bandhan', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
