insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('janmashtami', 'Krishna Janmashtami', 'Gokulashtami', 'Krishna''s midnight birthday', 'The birthday of Krishna, celebrated with fasting until midnight, songs and dramas of his childhood, swings for the baby Krishna, and human pyramids breaking pots of curd.', (select id from public.regions where slug = 'south-asia'), 'faith', 'Hindus, especially Vaishnava communities, in India, Nepal and worldwide', '{"kind":"table","calendar":"Hindu lunisolar calendar (eighth day of the dark half of Bhadrapada)","typicalMonths":[8,9]}'::jsonb, 'The eighth day of the dark half of Bhadrapada, in August or September.', 'The Bhagavata Purana tells of Krishna''s birth at midnight in a prison cell in Mathura, and of his father carrying him across the flooded Yamuna to safety in Gokul.', 'It celebrates divine love and playfulness: Krishna the butter thief, the cowherd and the teacher of the Bhagavad Gita.', array['Dahi Handi is risky: watch from a safe distance.', 'Temples are packed at midnight; arrive early.', 'Offer sweets made without onion or garlic if you bring prasad.']::text[], array['classical', 'bollywood']::text[], array['#0f1f4a', '#f2c014', '#1e88e5']::text[], 27.49, 77.67, 'https://en.wikipedia.org/wiki/Krishna_Janmashtami', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.