insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('navratri', 'Navratri', null, 'Nine nights of the goddess', 'Nine nights in honour of the goddess Durga in her many forms, celebrated with fasting, prayer, Golu doll displays and, above all, garba and dandiya dancing late into the night.', (select id from public.regions where slug = 'south-asia'), 'faith', 'Hindus across India, Nepal and the diaspora', '{"kind":"table","calendar":"Hindu lunisolar calendar (first nine days of the bright half of Ashvin)","typicalMonths":[9,10]}'::jsonb, 'Sharad Navratri runs for nine nights in September or October, ending the day before Dussehra.', 'Navratri celebrates the goddess Durga''s nine-night battle with the buffalo demon Mahishasura, told in the Devi Mahatmya. Each night is dedicated to one of her nine forms.', 'It honours feminine divine power, Shakti, and the triumph of good over evil.', array['Learn the basic garba step before joining the circle.', 'Wear traditional dress at garba events if you can; chaniya choli and kediyu are popular.', 'Remove shoes before entering a Golu display.']::text[], array['folk', 'bollywood']::text[], array['#1e0a23', '#e91e63', '#f2c014']::text[], 23.02, 72.57, 'https://en.wikipedia.org/wiki/Navaratri', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
