insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('dussehra', 'Dussehra', 'Vijayadashami', 'The tenth day of victory', 'The day after Navratri, when effigies of the demon king Ravana are burned at sunset to celebrate Rama''s victory, and Mysuru''s royal procession fills the streets.', (select id from public.regions where slug = 'south-asia'), 'faith', 'Hindus across India and Nepal', '{"kind":"table","calendar":"Hindu lunisolar calendar (tenth day of the bright half of Ashvin)","typicalMonths":[9,10]}'::jsonb, 'The tenth day of Ashvin, the day after Navratri, in September or October. Diwali follows about twenty days later.', 'Dussehra remembers Rama''s defeat of Ravana in the Ramayana, and in eastern India Durga''s victory over Mahishasura. Ramlila performances of the epic build up to it over the preceding nights.', 'It celebrates the victory of good over evil, and is considered an auspicious day to begin new ventures.', array['Effigy burnings draw large crowds and fireworks: keep a safe distance.', 'Accept tika and blessings from elders in Nepal with bowed head.', 'Ask before photographing Ramlila performers.']::text[], array['folk', 'bollywood']::text[], array['#fbf6ea', '#d84315', '#f2c014']::text[], 12.3, 76.64, 'https://en.wikipedia.org/wiki/Vijayadashami', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.lon