insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('karva-chauth', 'Karva Chauth', null, 'A fast until the moon rises', 'A day when many married women in northern India fast from sunrise until moonrise for the wellbeing of their spouses, ending the fast after sighting the moon through a sieve.', (select id from public.regions where slug = 'south-asia'), 'community', 'Hindu, and some Sikh, married women in northern and western India and the diaspora', '{"kind":"table","calendar":"Hindu lunisolar calendar (fourth day of the dark half of Kartika)","typicalMonths":[10,11]}'::jsonb, 'The fourth day after the full moon in Kartika, in October or November, about nine days before Diwali.', 'Karva Chauth developed in north-western India; a karva is the clay pot used in the rituals. Stories such as that of Queen Veervati are told during the evening puja.', 'It celebrates marriage and companionship. Customs are changing: in many couples today both partners fast, and observing it is a personal choice.', array['Never pressure anyone to fast; it is a personal choice.', 'If someone is fasting, avoid eating in front of them.', 'Mehndi and new bangles are traditional, but optional.']::text[], array['bollywood', 'folk']::text[], array['#4a0e1e', '#d81b60', '#f2c014']::text[], 30.73, 76.78, 'https://en.wikipedia.org/wiki/Karva_Chauth', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, 