insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('chhath-puja', 'Chhath Puja', null, 'Offerings to the setting and rising sun', 'A four-day festival of thanksgiving to the sun god Surya and Chhathi Maiya, when devotees fast and stand in rivers and ponds to make offerings at sunset and sunrise.', (select id from public.regions where slug = 'south-asia'), 'faith', 'Communities of Bihar, Jharkhand, eastern Uttar Pradesh and Nepal''s Madhesh, and their diaspora', '{"kind":"table","calendar":"Hindu lunisolar calendar (sixth day of the bright half of Kartika)","typicalMonths":[10,11]}'::jsonb, 'Six days after Diwali, in October or November, over four days.', 'Chhath is one of the oldest Vedic-rooted festivals still observed, centred on worship of the sun. It is most strongly associated with the Bhojpuri, Maithili and Magahi-speaking regions.', 'It gives thanks for life and the harvest. Its rituals are known for their purity, discipline and equality: everyone stands in the same water.', array['Keep the ghats clean and do not litter the water.', 'Do not touch the offerings of those who are fasting.', 'Help elderly devotees in and out of the water.']::text[], array['folk', 'traditional']::text[], array['#fbf6ea', '#ef6c00', '#f9a825']::text[], 25.59, 85.14, 'https://en.wikipedia.org/wiki/Chhath', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitud