insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('guru-nanak-jayanti', 'Guru Nanak Jayanti', 'Gurpurab', 'The birth of the first Sikh Guru', 'The birth anniversary of Guru Nanak, founder of Sikhism, marked with continuous readings of the Guru Granth Sahib, dawn processions, illuminated gurdwaras and langar for all.', (select id from public.regions where slug = 'south-asia'), 'faith', 'Sikhs worldwide, and many Hindus and others who revere Guru Nanak', '{"kind":"table","calendar":"Hindu lunisolar calendar (full moon of Kartika)","typicalMonths":[11]}'::jsonb, 'Celebrated on the full moon of Kartika, in November.', 'Guru Nanak was born in 1469 at Talwandi, now Nankana Sahib in Pakistan. He taught devotion to one God, equality of all people and honest work, and travelled widely sharing his message.', 'It celebrates his teachings: naam japna (remembering God), kirat karni (honest work) and vand chakna (sharing with others).', array['Cover your head and remove shoes in the gurdwara.', 'Sit on the floor for langar; everyone eats together.', 'Tobacco and alcohol are not allowed on gurdwara premises.']::text[], array['traditional', 'classical']::text[], array['#fbf6ea', '#f28c1e', '#1f3c88']::text[], 31.62, 74.88, 'https://en.wikipedia.org/wiki/Guru_Nanak_Gurpurab', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longit