insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('hornbill-festival', 'Hornbill Festival', null, 'The festival of festivals of Nagaland', 'Ten days in which Nagaland''s tribes gather at Kisama Heritage Village to share their dances, songs, games, crafts and food, named after the hornbill bird revered in Naga folklore.', (select id from public.regions where slug = 'south-asia'), 'arts', 'The Naga tribes of Nagaland, with visitors from across India and abroad', '{"kind":"fixed","month":12,"day":1,"durationDays":10}'::jsonb, 'Held every year from 1 to 10 December, beginning on Nagaland''s Statehood Day.', 'The state government started the festival in 2000 to bring together the traditions of Nagaland''s many tribes in one place and to encourage tourism. It is held at Kisama, near Kohima.', 'It celebrates the diversity and living culture of the Naga peoples, whose festivals are otherwise spread across the year.', array['Ask before photographing performers in traditional dress.', 'Hornbill feathers and regalia are sacred heirlooms: never touch them.', 'Many local dishes contain pork or smoked meat; ask if you have dietary needs.']::text[], array['folk', 'rock']::text[], array['#1a1a1a', '#c62828', '#f2c014']::text[], 25.62, 94.12, 'https://en.wikipedia.org/wiki/Hornbill_Festival', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude 