insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('fete-de-la-musique', 'Fête de la Musique', null, 'A whole country playing music in the street', 'On the longest day of the year, musicians of every level play for free in streets, parks and squares across France, and in hundreds of cities worldwide.', (select id from public.regions where slug = 'europe'), 'arts', 'Everyone in France, and in more than 100 countries that have adopted it', '{"kind":"fixed","month":6,"day":21,"durationDays":1}'::jsonb, 'Every year on 21 June, the summer solstice in the northern hemisphere.', 'The French Ministry of Culture launched the Fête de la Musique in 1982, inviting amateurs and professionals alike to play outdoors. It quickly spread across Europe and the world as World Music Day.', 'It celebrates music as something everyone can make and share: all concerts are free and anyone can play.', array['Concerts are free: tipping street musicians is welcome but optional.', 'Public transport runs late in big cities; plan your way home.', 'Keep noise down after the official end time in residential streets.']::text[], array['indie', 'electronic']::text[], array['#14122a', '#1e88e5', '#e53935']::text[], 48.86, 2.35, 'https://en.wikipedia.org/wiki/Fête_de_la_Musique', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
