insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('kings-day', 'King''s Day', 'Koningsdag', 'The Netherlands turns orange', 'The Dutch national celebration of the King''s birthday, when the whole country dresses in orange, streets become a giant flea market and canals fill with party boats.', (select id from public.regions where slug = 'europe'), 'community', 'Everyone in the Netherlands and Dutch communities abroad', '{"kind":"fixed","month":4,"day":27,"durationDays":1}'::jsonb, '27 April, King Willem-Alexander''s birthday; moved to the 26th when the 27th is a Sunday.', 'The holiday began as Princess''s Day in 1885 for the future Queen Wilhelmina. It became Queen''s Day and, since 2014, King''s Day, following the monarch''s birthday.', 'It is a day of national togetherness and informality: anyone may sell their old things on the street without a permit.', array['Wear something orange.', 'Markets open early: claim your spot with chalk or tape where it is allowed.', 'Use public toilets and bins; streets get crowded.']::text[], array['electronic', 'rock']::text[], array['#fbf6ea', '#f57c00', '#1e3a8a']::text[], 52.37, 4.9, 'https://en.wikipedia.org/wiki/Koningsdag', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
