insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('barranquilla-carnival', 'Barranquilla Carnival', 'Carnaval de Barranquilla', 'Colombia''s carnival of the Caribbean coast', 'Four days of parades, masks and music on Colombia''s Caribbean coast, blending Spanish, African and Indigenous traditions; UNESCO lists it as a Masterpiece of the Oral and Intangible Heritage of Humanity.', (select id from public.regions where slug = 'latin-america'), 'arts', 'Barranquilla and communities across Colombia''s Caribbean region', '{"kind":"easter-offset","offsetDays":-50,"durationDays":4}'::jsonb, 'The four days before Ash Wednesday, from Saturday to Shrove Tuesday, in February or March.', 'Carnival in Barranquilla grew from colonial-era celebrations in Cartagena and took its modern form in the 19th century. In 2003 UNESCO proclaimed it a Masterpiece of the Oral and Intangible Heritage of Humanity.', 'It celebrates the mixed heritage of the Caribbean coast through dance, satire and music, ending with the symbolic burial of Joselito Carnaval.', array['Expect to be sprayed with foam and flour.', 'Keep valuables minimal in the crowds.', 'Ask before photographing dancers up close.']::text[], array['latin', 'salsa']::text[], array['#fbf6ea', '#f9a825', '#d32f2f']::text[], 10.96, -74.8, 'https://en.wikipedia.org/wiki/Barranquilla''s_Carnival', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
