insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('maslenitsa', 'Maslenitsa', 'Масленица', 'Pancake week before Lent', 'A week-long farewell to winter before Orthodox Lent, with stacks of blini, sledging, fist-fight games and the burning of a straw effigy of Lady Maslenitsa.', (select id from public.regions where slug = 'europe'), 'spring', 'Russians and other Eastern Slavic peoples, in Russia, Ukraine, Belarus and the diaspora', '{"kind":"table","calendar":"Orthodox church calendar (the week before Great Lent)","typicalMonths":[2,3]}'::jsonb, 'The week before Orthodox Great Lent, eight weeks before Orthodox Easter, in February or March.', 'Maslenitsa has roots in pre-Christian Slavic rites marking the end of winter and was later absorbed into the Orthodox calendar as Cheesefare Week, the last week when dairy may be eaten before Lent.', 'It is a festival of abundance, forgiveness and the coming of spring: the last day is Forgiveness Sunday, when people ask each other''s pardon.', array['Accept blini when offered; refusing is impolite.', 'On Forgiveness Sunday, answer ''God will forgive'' when someone asks your pardon.', 'Stand well back from the bonfire.']::text[], array['folk', 'classical']::text[], array['#fbf6ea', '#e65100', '#1565c0']::text[], 55.75, 37.62, 'https://en.wikipedia.org/wiki/Maslenitsa', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
