insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('orthodox-easter-greece', 'Greek Orthodox Easter', 'Pascha', 'Candles at midnight and red eggs', 'The most important feast of the Greek year: a midnight service where the Holy Light passes from candle to candle, followed by fireworks, red eggs and family feasts.', (select id from public.regions where slug = 'europe'), 'faith', 'Greek Orthodox Christians in Greece, Cyprus and the diaspora', '{"kind":"table","calendar":"Orthodox church calendar (Julian computation of Easter)","typicalMonths":[4,5]}'::jsonb, 'Orthodox Easter is calculated on the Julian calendar, so it usually falls one to five weeks after Western Easter, in April or May.', 'Pascha celebrates the Resurrection and has been the centre of the Orthodox year since the early Church. Many Greek customs, such as red eggs, are centuries old.', 'It is a celebration of light over darkness and life over death, and the great reunion of families after the Lenten fast.', array['Dress modestly for church.', 'Answer ''Christos Anesti'' (Christ is risen) with ''Alithos Anesti'' (Truly He is risen).', 'Shield your candle flame and carry it home if you can.']::text[], array['traditional', 'classical']::text[], array['#fbf6ea', '#c62828', '#1565c0']::text[], 37.98, 23.73, 'https://en.wikipedia.org/wiki/Easter_in_Greece', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
