insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('thingyan', 'Thingyan', 'သင်္ကြန်', 'Myanmar''s water festival new year', 'Myanmar''s New Year water festival, when streets become water fights to wash away the old year''s misdeeds, alongside merit-making at pagodas and kindness to elders.', (select id from public.regions where slug = 'southeast-asia'), 'new-year', 'Buddhists of Myanmar and the diaspora', '{"kind":"fixed","month":4,"day":13,"durationDays":4}'::jsonb, 'Usually 13 to 16 April, with the New Year on the 17th; the exact days are announced each year.', 'Thingyan comes from the Sanskrit sankranti, the sun''s passage into Aries. It shares its roots with Songkran in Thailand and other Southeast Asian new years.', 'Water symbolically washes away the sins and misfortunes of the old year, and the new year begins with merit-making and respect for elders.', array['Expect to get soaked; protect your phone.', 'Don''t throw water at monks, the elderly or people who clearly don''t want to play.', 'Dress modestly when visiting pagodas.']::text[], array['traditional', 'folk']::text[], array['#fbf6ea', '#f9a825', '#0277bd']::text[], 16.84, 96.17, 'https://en.wikipedia.org/wiki/Thingyan', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verific