insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('bon-om-touk', 'Bon Om Touk', 'បុណ្យអុំទូក', 'Cambodia''s water and moon festival', 'Cambodia''s Water Festival, with dragon-boat races on the Tonlé Sap in Phnom Penh, illuminated floats at night and salutes to the moon with ambok, flattened rice.', (select id from public.regions where slug = 'southeast-asia'), 'harvest', 'Cambodians, with hundreds of thousands travelling to Phnom Penh', '{"kind":"table","calendar":"Khmer lunar calendar (full moon of Kadeuk)","typicalMonths":[10,11]}'::jsonb, 'Three days at the full moon of the Khmer month of Kadeuk, in October or November.', 'The festival marks the remarkable reversal of the Tonlé Sap river at the end of the rainy season. Boat races are said to recall the naval forces of the Angkor kings.', 'It gives thanks to the river and the moon for the fish and rice harvest, and marks the end of the rainy season.', array['Riverbanks are very crowded; follow police directions.', 'Dress modestly near the Royal Palace and pagodas.', 'Keep an eye on children near the water.']::text[], array['traditional', 'world']::text[], array['#0d1b2a', '#f9a825', '#e53935']::text[], 11.56, 104.93, 'https://en.wikipedia.org/wiki/Bon_Om_Touk', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
