insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('sao-joao-porto', 'São João in Porto', 'Festa de São João do Porto', 'Porto''s night of hammers and sardines', 'On Midsummer Night the whole of Porto stays up to celebrate Saint John: people tap each other on the head with plastic hammers, light paper balloons and watch fireworks over the Douro.', (select id from public.regions where slug = 'europe'), 'community', 'Porto and northern Portugal', '{"kind":"fixed","month":6,"day":23,"durationDays":2}'::jsonb, 'The night of 23 June into 24 June, the feast of Saint John the Baptist.', 'The feast of Saint John replaced older midsummer celebrations. The plastic hammers, now the festival''s emblem, appeared in the 1960s, replacing leeks and garlic flowers.', 'It is Porto''s great night of community: neighbours, families and strangers celebrate together until dawn.', array['Hammer taps are gentle and for fun; don''t hit hard.', 'Basil pots (manjericos) come with a love poem; give one to someone special.', 'The crowds are huge after midnight; agree a meeting point.']::text[], array['folk', 'world']::text[], array['#fbf6ea', '#1565c0', '#f9a825']::text[], 41.15, -8.61, 'https://en.wikipedia.org/wiki/Saint_John%27s_Festival_(Portugal)', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_ur