insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('vendimia', 'Vendimia', 'Fiesta Nacional de la Vendimia', 'Argentina''s grape harvest festival', 'Mendoza celebrates the grape harvest with blessings of the fruit, parades of carts and queens, and a huge night show in an amphitheatre in the Andean foothills.', (select id from public.regions where slug = 'latin-america'), 'harvest', 'Mendoza and Argentina''s wine regions', '{"kind":"seasonal","months":[2,3]}'::jsonb, 'Held in late February and early March, with the main events on the first weekend of March.', 'The national festival began in 1936 to celebrate the work of vineyard labourers and the harvest in Mendoza, Argentina''s main wine region.', 'It honours the people and the land behind the harvest, with the Bendición de los Frutos, the blessing of the fruit.', array['Book accommodation early; Mendoza fills up.', 'Drink responsibly and arrange transport if you visit wineries.', 'Parades are long; bring water and a hat.']::text[], array['folk', 'latin']::text[], array['#fbf6ea', '#6a1b4d', '#7cb342']::text[], -32.89, -68.83, 'https://en.wikipedia.org/wiki/National_Grape_Harvest_Festival', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
