insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('quebec-winter-carnival', 'Quebec Winter Carnival', 'Carnaval de Québec', 'The world''s biggest winter carnival', 'Quebec City celebrates the depths of winter with ice palaces, snow sculptures, night parades, canoe races on the frozen St Lawrence and its snowman mascot, Bonhomme.', (select id from public.regions where slug = 'north-america'), 'community', 'Quebec City and visitors from across Canada', '{"kind":"seasonal","months":[2]}'::jsonb, 'Held for about ten days in late January and February; dates are announced each year.', 'Winter carnivals were held in Quebec City from the 1890s; the modern carnival began in 1955 and Bonhomme Carnaval became its emblem.', 'It turns the hardest season into a celebration of community, French-Canadian culture and life outdoors.', array['Dress in many warm layers; temperatures can fall below -20 °C.', 'Wear the Effigie, the carnival pass, to enter official sites.', 'Greet Bonhomme with a hug, not a handshake.']::text[], array['folk', 'rock']::text[], array['#eaf2fb', '#c62828', '#1565c0']::text[], 46.81, -71.21, 'https://en.wikipedia.org/wiki/Quebec_Winter_Carnival', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
