insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('osun-osogbo', 'Osun-Osogbo Festival', null, 'The sacred grove of the river goddess', 'A two-week Yoruba festival honouring Osun, goddess of the river and fertility, culminating in a procession to the sacred grove at Osogbo, a UNESCO World Heritage Site.', (select id from public.regions where slug = 'africa'), 'faith', 'Yoruba devotees of Osun, people of Osogbo, and visitors from Nigeria and the diaspora', '{"kind":"seasonal","months":[8]}'::jsonb, 'Held over about two weeks in August; the grand finale date is set each year by the traditional authorities.', 'The festival is said to date back over 600 years to the founding of Osogbo, when the goddess Osun is believed to have promised to protect the town. The sacred grove became a UNESCO World Heritage Site in 2005.', 'It renews the bond between the people of Osogbo and the goddess, with prayers for fertility, protection and prosperity.', array['Follow the guidance of priests and guides in the sacred grove.', 'Do not photograph the Arugba without permission.', 'Respect the river and grove; do not litter.']::text[], array['afrobeats', 'traditional']::text[], array['#fbf6ea', '#f9a825', '#2e7d32']::text[], 7.76, 4.55, 'https://en.wikipedia.org/wiki/Osun-Osogbo', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
