insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('fes-sacred-music', 'Fes Festival of World Sacred Music', null, 'Spiritual music in a medieval city', 'An annual festival in Fes, Morocco, where Sufi brotherhoods, gospel choirs, Andalusian orchestras and sacred musicians from around the world perform in palaces and gardens.', (select id from public.regions where slug = 'africa'), 'arts', 'Audiences from Morocco and around the world', '{"kind":"seasonal","months":[5,6]}'::jsonb, 'Held for about a week in late May or June; dates are announced each year.', 'The festival was founded in 1994, after the Gulf War, as a meeting of spiritual traditions through music. Fes, with its medieval medina, is Morocco''s spiritual and scholarly capital.', 'It celebrates dialogue between faiths and cultures, with music as a shared language.', array['Dress modestly in the medina.', 'Ask before photographing people.', 'Some sites are religious; follow guides'' instructions.']::text[], array['world', 'classical']::text[], array['#fbf6ea', '#1565c0', '#00897b']::text[], 34.06, -4.98, 'https://en.wikipedia.org/wiki/Fes_Festival_of_World_Sacred_Music', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
