insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('santiago-de-cuba-carnival', 'Santiago de Cuba Carnival', null, 'Cuba''s oldest and loudest carnival', 'In July, Santiago de Cuba fills with congas, comparsas and paper-lantern parades, the climax of Cuba''s Afro-Caribbean carnival tradition.', (select id from public.regions where slug = 'latin-america'), 'arts', 'Santiago de Cuba and visitors from across the island', '{"kind":"seasonal","months":[7]}'::jsonb, 'Held in July, traditionally around the feast of Saint James (Santiago) on 25 July.', 'Santiago''s carnival grew from colonial feasts of Saint James and from the celebrations of enslaved Africans and their cabildos, which brought drums, dances and the conga.', 'It celebrates the Afro-Cuban roots of Cuban music and the identity of Cuba''s eastern capital.', array['Follow the conga, but keep your belongings close.', 'Ask before photographing dancers.', 'Drink plenty of water in the July heat.']::text[], array['salsa', 'latin']::text[], array['#fbf6ea', '#d32f2f', '#1565c0']::text[], 20.02, -75.82, 'https://en.wikipedia.org/wiki/Carnival_of_Santiago_de_Cuba', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
