insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('carnival-of-binche', 'Carnival of Binche', null, 'The Gilles of Wallonia', 'In the small Belgian town of Binche, hundreds of Gilles in wax masks, ostrich-feather hats and bells dance through the streets throwing oranges, a carnival UNESCO recognises as intangible heritage.', (select id from public.regions where slug = 'europe'), 'arts', 'The people of Binche and visitors from across Belgium', '{"kind":"easter-offset","offsetDays":-49,"durationDays":3}'::jsonb, 'From the Sunday to Shrove Tuesday before Ash Wednesday, in February or March.', 'The carnival is documented since the 14th century. Its famous Gilles appear on Shrove Tuesday; UNESCO proclaimed the carnival a Masterpiece of the Oral and Intangible Heritage of Humanity in 2003.', 'Being a Gille is a great honour passed down through families of Binche; the carnival is a ritual of the town''s identity.', array['Catch the oranges; never throw them back at the Gilles.', 'Don''t touch a Gille''s costume.', 'Only men from Binche may be Gilles; it is a local tradition.']::text[], array['folk', 'traditional']::text[], array['#fbf6ea', '#f57c00', '#c62828']::text[], 50.41, 4.17, 'https://en.wikipedia.org/wiki/Carnival_of_Binche', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
