insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('basel-fasnacht', 'Basel Fasnacht', 'Basler Fasnacht', 'The three most beautiful days', 'Switzerland''s largest carnival begins at 4 a.m. with the lights of Basel switched off, as lantern-carrying cliques march through the old town playing piccolos and drums for 72 hours.', (select id from public.regions where slug = 'europe'), 'arts', 'Basel and visitors from across Switzerland', '{"kind":"easter-offset","offsetDays":-41,"durationDays":3}'::jsonb, 'Starts at 4 a.m. on the Monday after Ash Wednesday and lasts exactly 72 hours, in February or March.', 'Basel''s Fasnacht is first recorded in the 14th century. Unusually, it starts after Ash Wednesday, following the Protestant calendar adopted at the Reformation. UNESCO recognised it as intangible heritage in 2017.', 'Locals call it ''die drey scheenschte Dääg'', the three most beautiful days, a time of satire, music and community.', array['Don''t use flash at the Morgestraich; the darkness is part of it.', 'Don''t wear a mask unless you are in a clique.', 'Buy a Blaggedde badge to support the cliques.']::text[], array['folk', 'classical']::text[], array['#14122a', '#f9a825', '#c62828']::text[], 47.56, 7.59, 'https://en.wikipedia.org/wiki/Carnival_of_Basel', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
