insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('smigus-dyngus', 'Śmigus-Dyngus', 'Lany Poniedziałek', 'Wet Monday', 'On Easter Monday, Poland turns into a giant water fight: children and adults douse each other with buckets, water pistols and bottles, after a weekend of painted eggs and blessed Easter baskets.', (select id from public.regions where slug = 'europe'), 'spring', 'People across Poland and Polish communities abroad', '{"kind":"easter-offset","offsetDays":1,"durationDays":1}'::jsonb, 'Easter Monday, in March or April.', 'The custom blends a pre-Christian spring rite of cleansing with water with the Christian Easter season. It is recorded in Poland since the Middle Ages, when it was linked with the baptism of Mieszko I in 966.', 'Water stands for cleansing and new life in spring; the day is a joyful release after Lent and Easter''s solemn services.', array['Expect to get wet; leave your phone at home or in a bag.', 'Don''t soak the elderly or people in formal dress.', 'Water only: no dirty water or ice.']::text[], array['folk', 'traditional']::text[], array['#fbf6ea', '#1e88e5', '#c62828']::text[], 50.06, 19.94, 'https://en.wikipedia.org/wiki/Śmigus-dyngus', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
