insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('kupala-night', 'Kupala Night', 'Ivana Kupala', 'Midsummer fires and flower wreaths', 'A midsummer night when people in Ukraine jump over bonfires, float flower wreaths on rivers and search the woods for the legendary fern flower.', (select id from public.regions where slug = 'europe'), 'community', 'Ukrainians and other Eastern Slavic peoples', '{"kind":"seasonal","months":[6,7]}'::jsonb, 'Traditionally the night of 6 to 7 July; since the Ukrainian church calendar reform of 2023, many now celebrate on 23 to 24 June.', 'Kupala has roots in ancient Slavic midsummer rites honouring the sun, water and fertility. The Church linked it to the feast of John the Baptist, giving the name Ivan Kupala.', 'It celebrates the height of summer, youth and love, and the purifying power of fire and water.', array['Jump over a fire only when it has burned down and it''s safe.', 'Swim only where it is safe and permitted.', 'Ask before joining a circle dance.']::text[], array['folk', 'traditional']::text[], array['#fbf6ea', '#1565c0', '#f9a825']::text[], 50.45, 30.52, 'https://en.wikipedia.org/wiki/Kupala_Night', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
