insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('masopust', 'Masopust', null, 'Czech carnival of masks', 'The Czech carnival before Lent, when masked processions led by the bear and the horse go door to door through villages, with music, dancing and doughnuts.', (select id from public.regions where slug = 'europe'), 'arts', 'Towns and villages across Czechia', '{"kind":"easter-offset","offsetDays":-50,"durationDays":4}'::jsonb, 'The days before Ash Wednesday, ending on Shrove Tuesday, in February or March.', 'Masopust (''meat fast'') marks the last feasting before Lent and has been recorded since the Middle Ages. The masked door-to-door processions of the Hlinsko region were inscribed by UNESCO in 2010.', 'It brings villages together to say goodbye to winter with humour, masks and food.', array['Masks may ask for a small donation or a drink; join in the fun.', 'Don''t remove or touch someone''s mask.', 'Ask before photographing close up.']::text[], array['folk', 'traditional']::text[], array['#fbf6ea', '#c62828', '#1565c0']::text[], 50.08, 14.44, 'https://en.wikipedia.org/wiki/Masopust', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
