insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('busojaras', 'Busójárás', null, 'Scaring away winter in Mohács', 'In the Hungarian town of Mohács, men in shaggy sheepskins and carved wooden masks, the busós, parade with noisemakers and burn a coffin to drive away winter.', (select id from public.regions where slug = 'europe'), 'spring', 'The Šokci and people of Mohács, with visitors from across Hungary', '{"kind":"easter-offset","offsetDays":-52,"durationDays":6}'::jsonb, 'Six days ending on Shrove Tuesday, in February or March.', 'The carnival comes from the Šokci, a Croatian community of Mohács. Legend links the masks to scaring off Ottoman occupiers; UNESCO inscribed the festival in 2009.', 'It is a ritual farewell to winter and welcome to spring, and a celebration of the town''s identity.', array['Busós may playfully grab or tease spectators; it''s part of it.', 'Stand back from the bonfire.', 'Wear warm clothes; it''s February on the Danube.']::text[], array['folk', 'traditional']::text[], array['#1a1a1a', '#c62828', '#f2e7cf']::text[], 45.99, 18.68, 'https://en.wikipedia.org/wiki/Busójárás', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
