insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('baba-marta', 'Baba Marta', null, 'Red and white threads for spring', 'On 1 March, Bulgarians give each other martenitsi, red and white woven tokens worn until they see a stork or a blossoming tree, to welcome spring and wish health.', (select id from public.regions where slug = 'europe'), 'spring', 'Bulgarians, and Romanians, Moldovans and others with similar customs', '{"kind":"fixed","month":3,"day":1,"durationDays":1}'::jsonb, '1 March every year; martenitsi are worn through the month.', 'The custom is centuries old and linked with Baba Marta, ''Grandmother March'', a moody figure whose temper is the changeable spring weather. UNESCO inscribed the martenitsa tradition in 2017, shared with Romania, Moldova and North Macedonia.', 'Red and white stand for health, life and purity; the tokens are a wish for a healthy, happy year.', array['Don''t buy a martenitsa for yourself: it should be given.', 'Wear it until you see a stork, a swallow or a blossoming tree.', 'Return the greeting ''Chestita Baba Marta''.']::text[], array['folk', 'traditional']::text[], array['#fbf6ea', '#c62828', '#ffffff']::text[], 42.7, 23.32, 'https://en.wikipedia.org/wiki/Martenitsa', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
