insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('sankt-hans', 'Sankt Hans Aften', null, 'Danish midsummer bonfires', 'On Midsummer Eve, Danes light bonfires on beaches and lakeshores, sing Holger Drachmann''s ''Midsommervisen'', and burn a straw witch to send her off to the Brocken.', (select id from public.regions where slug = 'europe'), 'community', 'Everyone in Denmark', '{"kind":"fixed","month":6,"day":23,"durationDays":1}'::jsonb, 'The evening of 23 June, the eve of the feast of Saint John.', 'Midsummer fires go back to pre-Christian solstice rites; the Church attached them to Saint John the Baptist. The burning of a witch figure became widespread in the 20th century.', 'It celebrates the light of the longest days and the community of summer evenings outdoors.', array['Bring a picnic and a blanket.', 'Fires are cancelled in very dry weather; follow local notices.', 'Join in the song even if you only know the chorus.']::text[], array['folk', 'indie']::text[], array['#fbf6ea', '#c62828', '#1565c0']::text[], 55.68, 12.57, 'https://en.wikipedia.org/wiki/Saint_John%27s_Eve', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
