insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('taiwan-lantern-festival', 'Taiwan Lantern Festival', '元宵節', 'Sky lanterns on the first full moon', 'On the 15th night of the lunar new year, Taiwan lights up with giant lantern displays, riddle-solving, sweet rice dumplings and thousands of wish-bearing sky lanterns rising from Pingxi.', (select id from public.regions where slug = 'east-asia'), 'light', 'People across Taiwan, as part of Lunar New Year', '{"kind":"table","calendar":"Chinese lunisolar calendar (15th day of the first month)","typicalMonths":[2,3]}'::jsonb, 'The first full moon of the lunar year, 15 days after Lunar New Year, in February or March.', 'The Lantern Festival dates back over 2,000 years in China. In Pingxi, sky lanterns were once used to signal to villagers that bandits had gone; today people write wishes on them.', 'It ends the Lunar New Year season with light, family reunion and wishes for the year ahead.', array['Release sky lanterns only at official sites, where debris is collected.', 'Fireworks festivals require protective gear.', 'Write kind, positive wishes on lanterns.']::text[], array['traditional', 'classical']::text[], array['#1a0a0a', '#e53935', '#f9a825']::text[], 25.03, 121.74, 'https://en.wikipedia.org/wiki/Lantern_Festival', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
