insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('paro-tsechu', 'Paro Tsechu', null, 'Masked dances in a Himalayan fortress', 'Bhutan''s most famous religious festival, where monks and laymen perform masked cham dances in the courtyard of Paro Dzong, ending at dawn with the unveiling of a giant thangka.', (select id from public.regions where slug = 'south-asia'), 'faith', 'Bhutanese Buddhists, with visitors from around the world', '{"kind":"seasonal","months":[3,4]}'::jsonb, 'Five days in the second month of the Bhutanese lunar calendar, in March or April.', 'Tsechus honour Guru Rinpoche, who brought Buddhism to Bhutan in the 8th century. Paro''s festival dates from the 17th century, when the dzong was built.', 'Watching the sacred dances is believed to bring blessings and cleanse sins; seeing the great thangka liberates the viewer.', array['Wear modest clothing; Bhutanese attend in national dress.', 'Don''t use flash or block the dancers.', 'Walk clockwise around religious buildings.']::text[], array['traditional', 'world']::text[], array['#fbf6ea', '#c62828', '#f9a825']::text[], 27.43, 89.41, 'https://en.wikipedia.org/wiki/Paro_Tsechu', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
