insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('lamu-cultural-festival', 'Lamu Cultural Festival', null, 'Swahili heritage on the Kenyan coast', 'The UNESCO World Heritage town of Lamu celebrates Swahili culture with dhow races, donkey races, poetry, henna, crafts and taarab music.', (select id from public.regions where slug = 'africa'), 'arts', 'The Swahili communities of Lamu and visitors', '{"kind":"seasonal","months":[11]}'::jsonb, 'Held over several days, usually in November; dates are announced each year.', 'The festival was started in 2001 to celebrate and protect the heritage of Lamu Old Town, the oldest continuously inhabited Swahili town in East Africa.', 'It keeps Swahili crafts, sailing, poetry and music alive for a new generation.', array['Dress modestly, covering shoulders and knees.', 'Ask before photographing people.', 'There are no cars in Lamu; give way to donkeys.']::text[], array['world', 'traditional']::text[], array['#fbf6ea', '#00838f', '#c62828']::text[], -2.27, 40.9, 'https://en.wikipedia.org/wiki/Lamu', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
