insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('sauti-za-busara', 'Sauti za Busara', null, 'Sounds of wisdom in Zanzibar', 'An African music festival in Stone Town, Zanzibar, showcasing artists from across the continent, from taarab and bongo flava to desert blues.', (select id from public.regions where slug = 'africa'), 'arts', 'Music lovers from East Africa and around the world', '{"kind":"seasonal","months":[2]}'::jsonb, 'Held over several days in February; dates are announced each year.', 'The festival was founded in 2004 and is held in the Old Fort of Stone Town, itself a UNESCO World Heritage Site.', 'Its name means ''sounds of wisdom''; it celebrates African music made in Africa.', array['Dress modestly in Stone Town.', 'Respect prayer times around mosques.', 'Support artists by buying their music.']::text[], array['afrobeats', 'world']::text[], array['#fbf6ea', '#2e7d32', '#f9a825']::text[], -6.16, 39.19, 'https://en.wikipedia.org/wiki/Sauti_za_Busara', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
