insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('saint-louis-jazz', 'Saint-Louis Jazz Festival', null, 'Jazz on the Senegal river', 'One of Africa''s oldest jazz festivals, filling the colonial island city of Saint-Louis with concerts, street music and jam sessions.', (select id from public.regions where slug = 'africa'), 'arts', 'Jazz lovers from Senegal, West Africa and beyond', '{"kind":"seasonal","months":[5,6]}'::jsonb, 'Usually held for several days in late May or early June; dates are announced each year.', 'The festival began in 1993 in Saint-Louis, the former capital of French West Africa, whose island old town is a UNESCO World Heritage Site.', 'It brings African and international jazz together and celebrates Senegal''s rich musical life.', array['Dress modestly when visiting mosques.', 'Bargain politely in markets.', 'Ask before photographing people.']::text[], array['jazz', 'world']::text[], array['#14122a', '#f9a825', '#1565c0']::text[], 16.02, -16.49, 'https://en.wikipedia.org/wiki/Saint-Louis_Jazz_Festival', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
