insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('fiestas-patrias-chile', 'Fiestas Patrias', 'Dieciocho', 'Chile''s national holidays', 'Chile celebrates independence and its armed forces with fondas, outdoor fairs of food, music and dancing, where the cueca, the national dance, is danced with handkerchiefs.', (select id from public.regions where slug = 'latin-america'), 'community', 'Everyone in Chile', '{"kind":"fixed","month":9,"day":18,"durationDays":2}'::jsonb, '18 September (Independence) and 19 September (Day of the Glories of the Army); celebrations often run all week.', 'On 18 September 1810 Chile''s first government junta was formed, the start of the road to independence. The 19th honours the army.', 'It is the great celebration of Chilean identity, food and folk culture.', array['Learn the cueca''s basic steps: you may be invited to dance.', 'Bring a handkerchief.', 'Public transport changes over the holidays; plan ahead.']::text[], array['folk', 'latin']::text[], array['#fbf6ea', '#d32f2f', '#1565c0']::text[], -33.45, -70.67, 'https://en.wikipedia.org/wiki/Fiestas_Patrias_(Chile)', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
