insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('oruro-carnival', 'Carnival of Oruro', null, 'The devil dance of the Andes', 'In the Bolivian mining city of Oruro, tens of thousands of dancers in spectacular masks and costumes parade for the Virgen del Socavón, a carnival UNESCO recognises as a masterpiece of intangible heritage.', (select id from public.regions where slug = 'latin-america'), 'faith', 'Oruro and dancers and visitors from across Bolivia', '{"kind":"easter-offset","offsetDays":-50,"durationDays":3}'::jsonb, 'The Saturday before Ash Wednesday and the days that follow, in February or March.', 'The carnival blends Andean rites to Pachamama and the Tío, lord of the mines, with Catholic devotion to the Virgen del Socavón, patroness of miners. UNESCO proclaimed it a Masterpiece of the Oral and Intangible Heritage of Humanity in 2001.', 'It is an act of devotion and a celebration of Bolivia''s mixed Andean and Spanish heritage.', array['Oruro is at 3,700 m: take altitude seriously.', 'Book a seat in the stands in advance.', 'Ask before photographing dancers close up.']::text[], array['folk', 'latin']::text[], array['#14122a', '#c62828', '#f9a825']::text[], -17.97, -67.11, 'https://en.wikipedia.org/wiki/Carnival_of_Oruro', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
