insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('dia-de-los-difuntos-ecuador', 'Día de los Difuntos', null, 'Ecuador''s Day of the Dead', 'On 2 November, Ecuadorian families visit and decorate the graves of their loved ones and share colada morada, a spiced purple fruit drink, with guaguas de pan, bread shaped like babies.', (select id from public.regions where slug = 'latin-america'), 'remembrance', 'Families across Ecuador, especially in the Andes', '{"kind":"fixed","month":11,"day":2,"durationDays":1}'::jsonb, '2 November every year, All Souls'' Day.', 'The day combines the Catholic All Souls'' Day with Andean customs of sharing food with the dead. Colada morada has roots in pre-Hispanic drinks made from purple maize.', 'It keeps loved ones close: families remember the dead with food, flowers and time together.', array['Cemeteries are family spaces: be quiet and respectful.', 'Ask before photographing graves or families.', 'Accept colada morada if offered.']::text[], array['folk', 'traditional']::text[], array['#2a0f3d', '#7b1fa2', '#f9a825']::text[], -0.18, -78.47, 'https://en.wikipedia.org/wiki/Colada_morada', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
