insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('goroka-show', 'Goroka Show', null, 'Papua New Guinea''s gathering of tribes', 'Over a hundred tribal groups from across Papua New Guinea''s highlands gather in Goroka in full traditional dress, with face paint, bird-of-paradise plumes and sing-sing dances.', (select id from public.regions where slug = 'oceania'), 'arts', 'Highland communities of Papua New Guinea and visitors', '{"kind":"seasonal","months":[9]}'::jsonb, 'Held over a weekend in September, around Independence Day on 16 September.', 'The show began in the 1950s, encouraged by colonial administrators, as a way to bring rival highland groups together peacefully. It has become the country''s most famous cultural festival.', 'It celebrates the extraordinary diversity of Papua New Guinea, where more than 800 languages are spoken.', array['Ask performers before photographing close up.', 'Feathers and costumes are heirlooms: don''t touch.', 'Follow the organisers'' guidance on safety.']::text[], array['traditional', 'world']::text[], array['#1a1a1a', '#f9a825', '#c62828']::text[], -6.08, 145.39, 'https://en.wikipedia.org/wiki/Goroka_Show', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
