insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('krampuslauf', 'Krampus Run', 'Krampuslauf', 'Saint Nicholas and his horned companions', 'On the eve of Saint Nicholas Day, horned, fur-clad Krampus figures with bells and carved wooden masks run through Alpine towns, while Saint Nicholas rewards well-behaved children.', (select id from public.regions where slug = 'europe'), 'community', 'Alpine communities in Austria and neighbouring regions', '{"kind":"fixed","month":12,"day":5,"durationDays":1}'::jsonb, 'The evening of 5 December, the eve of Saint Nicholas Day; many towns hold runs through late November and early December.', 'Krampus comes from pre-Christian Alpine winter traditions and became the companion of Saint Nicholas, punishing naughty children while the saint rewards good ones.', 'It is a theatrical winter ritual of good and mischief that brings Alpine villages together.', array['Krampuses may chase and tap spectators with switches; keep small children back.', 'Don''t grab masks or costumes.', 'Follow the barriers and stewards.']::text[], array['folk', 'traditional']::text[], array['#1a1a1a', '#c62828', '#e9e4d4']::text[], 47.8, 13.04, 'https://en.wikipedia.org/wiki/Krampus', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
