insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('janu', 'Jāņi', null, 'Latvia''s midsummer night', 'Latvia''s biggest holiday: on the shortest night, people wear oak and flower wreaths, sing līgo songs, eat caraway cheese and keep bonfires burning until sunrise.', (select id from public.regions where slug = 'europe'), 'community', 'Everyone in Latvia and Latvians abroad', '{"kind":"fixed","month":6,"day":23,"durationDays":2}'::jsonb, 'Līgo on 23 June and Jāņi on 24 June, both public holidays.', 'Jāņi is rooted in ancient Baltic solstice rites; its songs, the līgo dainas, form a large part of Latvia''s folk song heritage.', 'It celebrates the sun, fertility and the land, and is a cornerstone of Latvian identity.', array['Don''t go to sleep before sunrise if you can: it''s said to bring a sleepy year.', 'Accept caraway cheese when offered.', 'Jump over the fire only when it is safe.']::text[], array['folk', 'traditional']::text[], array['#fbf6ea', '#2e7d32', '#f9a825']::text[], 56.95, 24.11, 'https://en.wikipedia.org/wiki/Jāņi', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
