insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('uzgavenes', 'Užgavėnės', null, 'Lithuania chases winter away', 'Lithuania''s Shrove Tuesday carnival, when masked mummers go house to house, a battle is staged between fat Lašininis and thin Kanapinis, and an effigy called Morė is burned.', (select id from public.regions where slug = 'europe'), 'spring', 'People across Lithuania', '{"kind":"easter-offset","offsetDays":-47,"durationDays":1}'::jsonb, 'Shrove Tuesday, the day before Ash Wednesday, in February or March.', 'Užgavėnės combines pagan rites for the end of winter with the Christian season before Lent.', 'Laughter, masks and feasting drive out winter and welcome spring.', array['Give mummers a pancake or coin when they visit.', 'Keep a distance from the burning effigy.', 'Join in the noise: it scares winter away.']::text[], array['folk', 'traditional']::text[], array['#fbf6ea', '#2e7d32', '#c62828']::text[], 54.69, 25.28, 'https://en.wikipedia.org/wiki/Užgavėnės', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
