insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('thjodhatid', 'Þjóðhátíð', null, 'Iceland''s island festival', 'Each August, the Westman Islands off Iceland''s south coast host a huge outdoor festival with a valley full of tents, a giant bonfire, fireworks and a ''brekkusöngur'' singalong on the hillside.', (select id from public.regions where slug = 'europe'), 'arts', 'Icelanders, with the people of the Westman Islands as hosts', '{"kind":"seasonal","months":[7,8]}'::jsonb, 'The first weekend of August, over Iceland''s Commerce Day long weekend.', 'The festival began in 1874, when bad weather stopped islanders from travelling to the mainland for celebrations of a thousand years of settlement, so they held their own.', 'It is a celebration of island community and Icelandic music.', array['Book the ferry early.', 'Bring warm and waterproof clothes, even in August.', 'Respect the camping rules and clean up.']::text[], array['indie', 'rock']::text[], array['#0d1b2a', '#4fc3f7', '#f9a825']::text[], 63.44, -20.27, 'https://en.wikipedia.org/wiki/Þjóðhátíð', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
