insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('martisor', 'Mărțișor', null, 'Romania''s first-of-March token', 'On 1 March, Romanians and Moldovans give each other mărțișoare, small charms tied with red and white string, to welcome spring and wish luck.', (select id from public.regions where slug = 'europe'), 'spring', 'Romanians and Moldovans', '{"kind":"fixed","month":3,"day":1,"durationDays":1}'::jsonb, '1 March every year.', 'The custom is very old and shared across the Balkans; UNESCO inscribed it in 2017 together with Bulgaria''s martenitsa and similar traditions in Moldova and North Macedonia.', 'The red and white string stands for winter and spring, life and purity, and carries wishes for good health.', array['Give a mărțișor; don''t buy one for yourself.', 'Wear it pinned to your coat.', 'Hang it on a blossoming tree when spring arrives.']::text[], array['folk', 'traditional']::text[], array['#fbf6ea', '#c62828', '#ffffff']::text[], 44.43, 26.1, 'https://en.wikipedia.org/wiki/Mărțișor', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
