insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('nauryz', 'Nauryz', null, 'The steppe''s spring new year', 'Kazakhstan celebrates the spring equinox with yurts on city squares, horse games, music, and nauryz kozhe, a soup made from seven ingredients.', (select id from public.regions where slug = 'central-asia'), 'new-year', 'People across Kazakhstan and Central Asia', '{"kind":"fixed","month":3,"day":21,"durationDays":3}'::jsonb, '21 to 23 March, public holidays in Kazakhstan.', 'Nauryz shares its roots with Persian Nowruz and has been celebrated on the steppe for thousands of years; it was restored as a public holiday after independence in 1991.', 'It celebrates renewal, friendship and forgiveness: old quarrels should be forgotten.', array['Accept a bowl of nauryz kozhe when offered.', 'Greet elders first.', 'Remove shoes when entering a yurt.']::text[], array['folk', 'traditional']::text[], array['#fbf6ea', '#00acc1', '#f9a825']::text[], 43.24, 76.89, 'https://en.wikipedia.org/wiki/Nowruz_in_Kazakhstan', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
