insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('jerash-festival', 'Jerash Festival', null, 'Music among Roman ruins', 'Jordan''s summer festival of culture and arts, with concerts, dance, poetry and theatre staged in the Roman theatres and colonnades of ancient Jerash.', (select id from public.regions where slug = 'middle-east'), 'arts', 'Audiences from Jordan and the Arab world', '{"kind":"seasonal","months":[7,8]}'::jsonb, 'Held over two to three weeks in July or August; dates are announced each year.', 'The festival was founded in 1981 to bring the ruins of Gerasa, one of the best-preserved Roman cities outside Italy, back to life with the arts.', 'It celebrates Arab and international culture against the backdrop of Jordan''s heritage.', array['Dress modestly.', 'Stay hydrated in the summer heat.', 'Don''t climb on the ancient monuments.']::text[], array['world', 'classical']::text[], array['#fbf6ea', '#a1887f', '#c62828']::text[], 32.28, 35.89, 'https://en.wikipedia.org/wiki/Jerash_Festival', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
