insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('boun-bang-fai', 'Boun Bang Fai', null, 'The rocket festival', 'Before the rains, villages in Laos and north-east Thailand launch home-made bamboo rockets into the sky to remind the heavens to send rain for the rice crop, with music, processions and plenty of fun.', (select id from public.regions where slug = 'southeast-asia'), 'harvest', 'Lao communities in Laos and north-east Thailand', '{"kind":"seasonal","months":[5,6]}'::jsonb, 'Held in May or June, before the rice-planting season; each village sets its own date.', 'The festival comes from pre-Buddhist fertility rites; the rockets are said to remind the rain god Phaya Thaen to send the rains.', 'It asks for good rains and a successful rice harvest, and brings villages together.', array['Stand well back from the launch area.', 'Expect cheeky songs and humour.', 'Dress modestly when visiting temples.']::text[], array['traditional', 'folk']::text[], array['#fbf6ea', '#ef6c00', '#2e7d32']::text[], 17.97, 102.63, 'https://en.wikipedia.org/wiki/Rocket_Festival', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
