insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('kwita-izina', 'Kwita Izina', null, 'Naming the baby gorillas', 'Rwanda''s ceremony to name the mountain gorillas born in the past year, based on the Rwandan tradition of naming newborn children, with music, dance and conservation talks.', (select id from public.regions where slug = 'africa'), 'community', 'Rwandans, conservationists and visitors', '{"kind":"seasonal","months":[9]}'::jsonb, 'Usually held in September at the foot of the Virunga volcanoes; dates are announced each year.', 'The ceremony began in 2005, modelled on the traditional Rwandan naming of newborns, to celebrate the recovery of the mountain gorilla population.', 'It celebrates conservation and the communities who protect the gorillas.', array['Gorilla trekking needs a permit; follow the rangers.', 'Keep your distance from wildlife.', 'Rwanda bans plastic bags; don''t bring them.']::text[], array['afrobeats', 'traditional']::text[], array['#fbf6ea', '#2e7d32', '#1565c0']::text[], -1.48, 29.6, 'https://en.wikipedia.org/wiki/Kwita_Izina', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
