insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('festival-on-the-niger', 'Festival on the Niger', 'Festival sur le Niger', 'Music on the banks of the Niger', 'In Ségou, Mali, the riverside fills with concerts of Malian music, puppetry, crafts and canoe races, celebrating the culture of the Niger river.', (select id from public.regions where slug = 'africa'), 'arts', 'Malians and visitors from West Africa and beyond', '{"kind":"seasonal","months":[2]}'::jsonb, 'Held over several days, usually in early February; dates are announced each year.', 'The festival was founded in 2005 in Ségou, once capital of the Bambara Empire, to celebrate the cultures along the Niger.', 'It showcases Mali''s extraordinary musical heritage, from griots and the kora to desert blues.', array['Dress modestly.', 'Ask before photographing people.', 'Check current travel advice before planning a visit.']::text[], array['world', 'traditional']::text[], array['#fbf6ea', '#8d6e63', '#f9a825']::text[], 13.43, -6.26, 'https://en.wikipedia.org/wiki/Festival_sur_le_Niger', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
