insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('accompong-maroon-festival', 'Accompong Maroon Festival', null, 'Celebrating Maroon freedom', 'On 6 January, the Maroon town of Accompong in Jamaica''s Cockpit Country celebrates the 1739 peace treaty with the British and the birthday of the leader Cudjoe, with drumming, the abeng horn and traditional food.', (select id from public.regions where slug = 'latin-america'), 'remembrance', 'The Maroons of Accompong and visitors from across Jamaica', '{"kind":"fixed","month":1,"day":6,"durationDays":1}'::jsonb, '6 January every year.', 'The Maroons, Africans who escaped slavery, fought the British for decades before Captain Cudjoe signed a peace treaty in 1739 recognising their freedom and land.', 'It celebrates freedom, resistance and the survival of African traditions in Jamaica.', array['Respect sacred sites such as the Kindah tree.', 'Ask before photographing ceremonies.', 'Follow the guidance of the Maroon council.']::text[], array['traditional', 'world']::text[], array['#1a1a1a', '#2e7d32', '#f9a825']::text[], 18.23, -77.74, 'https://en.wikipedia.org/wiki/Accompong', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
