insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('haitian-kanaval', 'Haitian Kanaval', null, 'Rara, masks and music', 'Haiti''s carnival fills the streets with konpa bands on floats, masked figures, satirical songs and the rara bands whose bamboo trumpets carry on into Lent.', (select id from public.regions where slug = 'latin-america'), 'arts', 'People across Haiti and the diaspora', '{"kind":"easter-offset","offsetDays":-49,"durationDays":3}'::jsonb, 'The Sunday to Shrove Tuesday before Ash Wednesday, in February or March.', 'Haitian carnival blends French colonial carnival with African and Taíno traditions, and is a stage for political satire through its songs.', 'It is a celebration of Haitian music, art and resilience.', array['Check local conditions before attending.', 'Ask before photographing masked characters.', 'Keep valuables minimal in crowds.']::text[], array['world', 'latin']::text[], array['#fbf6ea', '#1565c0', '#c62828']::text[], 18.23, -72.53, 'https://en.wikipedia.org/wiki/Haitian_Carnival', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
