insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('diablos-danzantes-de-yare', 'Dancing Devils of Yare', 'Diablos Danzantes de Yare', 'Devils who bow to the Eucharist', 'On Corpus Christi, dancers in red costumes and painted devil masks dance through San Francisco de Yare in Venezuela before kneeling in surrender to the Eucharist, a tradition UNESCO lists as intangible heritage.', (select id from public.regions where slug = 'latin-america'), 'faith', 'The brotherhoods of San Francisco de Yare and other Venezuelan towns', '{"kind":"easter-offset","offsetDays":60,"durationDays":1}'::jsonb, 'Corpus Christi, sixty days after Easter, in May or June.', 'The tradition dates back to the 18th century and blends Spanish Catholic, African and Indigenous elements. UNESCO inscribed the Dancing Devils of Corpus Christi in 2012.', 'It dramatises the triumph of good over evil, as the devils submit to the Blessed Sacrament.', array['This is a religious ritual: be respectful during the kneeling.', 'Ask before photographing dancers.', 'Don''t touch the masks.']::text[], array['latin', 'traditional']::text[], array['#1a0a0a', '#d32f2f', '#f9a825']::text[], 10.18, -66.74, 'https://en.wikipedia.org/wiki/Dancing_Devils_of_Yare', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_st