insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('desfile-de-llamadas', 'Desfile de Llamadas', null, 'Candombe drums of Montevideo', 'During Uruguay''s long carnival, comparsas of candombe drummers and dancers parade through the Barrio Sur and Palermo neighbourhoods of Montevideo, celebrating Afro-Uruguayan heritage.', (select id from public.regions where slug = 'latin-america'), 'arts', 'Montevideo and candombe groups across Uruguay', '{"kind":"seasonal","months":[2]}'::jsonb, 'Held over two nights in February during Uruguay''s carnival; dates are announced each year.', 'Candombe was brought by enslaved Africans and kept alive in Montevideo''s southern neighbourhoods. UNESCO inscribed candombe in 2009.', 'It celebrates Afro-Uruguayan identity and the city''s neighbourhoods.', array['Don''t walk through a comparsa while it plays.', 'Bring cash for street food.', 'Ask before photographing up close.']::text[], array['latin', 'world']::text[], array['#14122a', '#1565c0', '#f9a825']::text[], -34.91, -56.19, 'https://en.wikipedia.org/wiki/Candombe', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
