insert into public.festivals (slug, name, local_name, tagline, summary, region_id, category, observed_by, date_rule, date_note, history, significance, etiquette, genres, palette, latitude, longitude, source_url, verification_status) values ('teuila-festival', 'Teuila Festival', null, 'Samoa''s week of culture', 'Samoa''s national festival of culture, named after the red ginger flower, with fire-knife dancing, fautasi longboat races, siva dances, tattoo demonstrations and a Miss Samoa pageant.', (select id from public.regions where slug = 'oceania'), 'arts', 'Samoans and visitors', '{"kind":"seasonal","months":[9]}'::jsonb, 'Held for about a week in September in Apia; dates are announced each year.', 'The festival began in 1991 to celebrate fa''a Samoa, the Samoan way of life, and to welcome visitors.', 'It celebrates Samoan culture, family and village life.', array['Dress modestly, covering shoulders and knees.', 'Respect Sunday, a day of rest and church.', 'Ask before photographing people.']::text[], array['traditional', 'world']::text[], array['#fbf6ea', '#c62828', '#2e7d32']::text[], -13.83, -171.76, 'https://en.wikipedia.org/wiki/Teuila_Festival', 'reference') on conflict (slug) do update set name = excluded.name, local_name = excluded.local_name, tagline = excluded.tagline, summary = excluded.summary, region_id = excluded.region_id, category = excluded.category, observed_by = excluded.observed_by, date_rule = excluded.date_rule, date_note = excluded.date_note, history = excluded.history, significance = excluded.significance, etiquette = excluded.etiquette, genres = excluded.genres, palette = excluded.palette, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url, verification_status = excluded.verification_status;
