insert into public.destinations (slug, name, country_id, kind, summary, landmarks, experiences, itinerary, latitude, longitude, source_url) values ('varanasi', 'Varanasi', (select id from public.countries where code = 'IN'), 'city', 'One of the oldest living cities in the world, built along the ghats of the Ganges.', array['Dashashwamedh Ghat', 'Kashi Vishwanath Temple', 'Sarnath, nearby']::text[], array['Evening Ganga aarti from the steps or a boat', 'Dev Deepavali, when the ghats are lined with lamps a fortnight after Diwali', 'Walking the silk-weaving lanes']::text[], array['Dawn boat ride along the ghats', 'Morning in the old city lanes and weaving workshops', 'Afternoon at Sarnath', 'Evening aarti at the river']::text[], 25.32, 83.01, 'https://en.wikipedia.org/wiki/Special:Search?search=Varanasi&go=Go') on conflict (slug) do update set name = excluded.name, country_id = excluded.country_id, kind = excluded.kind, summary = excluded.summary, landmarks = excluded.landmarks, experiences = excluded.experiences, itinerary = excluded.itinerary, latitude = excluded.latitude, longitude = excluded.longitude, source_url = excluded.source_url;
