insert into public.attire (slug, name, country_id, summary, textiles, craftsmanship, wearing, contemporary, source_url) values ('sari', 'Sari', (select id from public.countries where code = 'IN'), 'An unstitched length of cloth, usually five to nine metres, draped over a blouse and petticoat in dozens of regional styles.', array['Banarasi silk brocade', 'Kanchipuram silk', 'Bengal cotton and jamdani', 'Chanderi']::text[], 'Handloom saris can take weeks to weave; motifs and borders identify the weaving centre.', 'Anyone may wear a sari to a celebration when invited to. Ask a host or a shop to help with draping.', 'Designers pair saris with shirts, belts and jackets, and pre-draped versions are widely sold.', 'https://en.wikipedia.org/wiki/Special:Search?search=Sari&go=Go') on conflict (slug) do update set name = excluded.name, country_id = excluded.country_id, summary = excluded.summary, textiles = excluded.textiles, craftsmanship = excluded.craftsmanship, wearing = excluded.wearing, contemporary = excluded.contemporary, source_url = excluded.source_url;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'diwali'), (select id from public.attire where slug = 'sari')) on conflict do nothing;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'durga-puja'), (select id from public.attire where slug = 'sari')) on conflict do nothing;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'pongal'), (select id from public.attire where slug = 'sari')) on conflict do nothing;
insert into public.attire (slug, name, country_id, summary, textiles, craftsmanship, wearing, contemporary, source_url) values ('lehenga-choli', 'Lehenga choli', (select id from public.countries where code = 'IN'), 'A full skirt, fitted blouse and long scarf, worn for festivals, garba nights and weddings.', array['Silk', 'Georgette', 'Bandhani tie-dye', 'Mirror-work cotton']::text[], 'Embroidery traditions include zardozi metal thread, gota patti ribbon work and mirror work.', 'Lighter cotton sets are worn for Navratri dancing; heavier embroidered ones for evening functions.', 'Lightweight, pocketed and sustainably made lehengas are a focus of several contemporary labels.', 'https://en.wikipedia.org/wiki/Special:Search?search=Gagra%20choli&go=Go') on conflict (slug) do update set name = excluded.name, country_id = excluded.country_id, summary = excluded.summary, textiles = excluded.textiles, craftsmanship = excluded.craftsmanship, wearing = excluded.wearing, contemporary = excluded.contemporary, source_url = excluded.source_url;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'diwali'), (select id from public.attire where slug = 'lehenga-choli')) on conflict do nothing;
