insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'holi'), (select id from public.attire where slug = 'lehenga-choli')) on conflict do nothing;
insert into public.attire (slug, name, country_id, summary, textiles, craftsmanship, wearing, contemporary, source_url) values ('sherwani-kurta', 'Kurta and sherwani', (select id from public.countries where code = 'IN'), 'The kurta is a long tunic worn daily and for festivals; the sherwani is its formal, structured relative.', array['Cotton', 'Silk', 'Linen', 'Brocade']::text[], 'Chikankari from Lucknow and block printing from Rajasthan are among the best-known kurta crafts.', 'A plain kurta with trousers suits almost any South Asian celebration.', 'Short kurtas, Nehru jackets and indo-western cuts are common festive choices.', 'https://en.wikipedia.org/wiki/Special:Search?search=Kurta&go=Go') on conflict (slug) do update set name = excluded.name, country_id = excluded.country_id, summary = excluded.summary, textiles = excluded.textiles, craftsmanship = excluded.craftsmanship, wearing = excluded.wearing, contemporary = excluded.contemporary, source_url = excluded.source_url;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'diwali'), (select id from public.attire where slug = 'sherwani-kurta')) on conflict do nothing;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'eid-al-fitr'), (select id from public.attire where slug = 'sherwani-kurta')) on conflict do nothing;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'ganesh-chaturthi'), (select id from public.attire where slug = 'sherwani-kurta')) on conflict do nothing;
insert into public.attire (slug, name, country_id, summary, textiles, craftsmanship, wearing, contemporary, source_url) values ('kasavu', 'Kasavu sari and mundu', (select id from public.countries where code = 'IN'), 'Off-white handloom cotton with a gold border, worn across Kerala for Onam.', array['Handloom cotton', 'Zari (gold thread) border']::text[], 'Balaramapuram, Chendamangalam and Kuthampully are known weaving centres.', 'Both the sari and the men''s mundu are worn by people of every community in Kerala at Onam.', 'Coloured borders and kasavu fabric in dresses and shirts are popular updates.', 'https://en.wikipedia.org/wiki/Special:Search?search=Kerala%20sari&go=Go') on conflict (slug) do update set name = excluded.name, country_id = excluded.country_id, summary = excluded.summary, textiles = excluded.textiles, craftsmanship = excluded.craftsmanship, wearing = excluded.wearing, contemporary = excluded.contemporary, source_url = excluded.source_url;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'onam'), (select id from public.attire where slug = 'kasavu')) on conflict do nothing;
insert into public.attire (slug, name, country_id, summary, textiles, craftsmanship, wearing, contemporary, source_url) values ('shalwar-kameez', 'Shalwar kameez', (select id from public.countries where code = 'PK'), 'A tunic over loose trousers, worn by men and women across South Asia and the standard choice for Eid.', array['Lawn cotton', 'Silk', 'Chiffon']::text[], 'Embroidery, block print and hand-finished necklines distinguish festive sets.', 'New clothes for Eid morning are a cherished custom; modest cuts are usual for prayers.', 'Each season brings new Eid collections in changing lengths and silhouettes.', 'https://en.wikipedia.org/wiki/Special:Search?search=Shalwar%20kameez&go=Go') on conflict (slug) do update set name = excluded.name, country_id = excluded.country_id, summary = excluded.summary, textiles = excluded.textiles, craftsmanship = excluded.craftsmanship, wearing = excluded.wearing, contemporary = excluded.contemporary, source_url = excluded.source_url;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'eid-al-fitr'), (select id from public.attire where slug = 'shalwar-kameez')) on conflict do nothing;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'eid-al-adha'), (select id from public.attire where slug = 'shalwar-kameez')) on conflict do nothing;
insert into public.attire (slug, name, country_id, summary, textiles, craftsmanship, wearing, contemporary, source_url) values ('hanfu', 'Hanfu', (select id from public.countries where code = 'CN'), 'Historical Han Chinese dress of flowing robes and cross-collars, revived by a large youth movement.', array['Silk', 'Linen', 'Brocade']::text[], 'Styles reference specific dynasties, from Tang high-waisted skirts to Ming pleated mamianqun.', 'Often worn for festivals, photographs and visits to historic sites.', 'Everyday hanfu mixes historical cuts with modern fabrics.', 'https://en.wikipedia.org/wiki/Special:Search?search=Hanfu&go=Go') on conflict (slug) do update set name = excluded.name, country_id = excluded.country_id, summary = excluded.summary, textiles = excluded.textiles, craftsmanship = excluded.craftsmanship, wearing = excluded.wearing, contemporary = excluded.contemporary, source_url = excluded.source_url;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'lunar-new-year'), (select id from public.attire where slug = 'hanfu')) on conflict do nothing;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'mid-autumn-festival'), (select id from public.attire where slug = 'hanfu')) on conflict do nothing;
insert into public.attire (slug, name, country_id, summary, textiles, craftsmanship, wearing, contemporary, source_url) values ('qipao', 'Qipao', (select id from public.countries where code = 'CN'), 'A fitted one-piece dress with a high collar and side fastenings, also called cheongsam.', array['Silk brocade', 'Velvet', 'Cotton']::text[], 'Hand-knotted pankou buttons and piped edges mark careful tailoring.', 'Red and gold are favoured at New Year; white and black are generally avoided for celebrations.', 'Looser cuts and shorter lengths have brought it back into daily wear.', 'https://en.wikipedia.org/wiki/Special:Search?search=Cheongsam&go=Go') on conflict (slug) do update set name = excluded.name, country_id = excluded.country_id, summary = excluded.summary, textiles = excluded.textiles, craftsmanship = excluded.craftsmanship, wearing = excluded.wearing, contemporary = excluded.contemporary, source_url = excluded.source_url;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'lunar-new-year'), (select id from public.attire where slug = 'qipao')) on conflict do nothing;
insert into public.attire (slug, name, country_id, summary, textiles, craftsmanship, wearing, contemporary, source_url) values ('hanbok', 'Hanbok', (select id from public.countries where code = 'KR'), 'Korean dress of a short jacket with a full skirt or loose trousers, in clear colours and simple lines.', array['Silk', 'Ramie', 'Cotton']::text[], 'The curve of the sleeve and the tie of the jacket ribbon (goreum) are points of pride.', 'Worn for Seollal and Chuseok family rites; visitors can rent hanbok near the palaces in Seoul.', 'Modern hanbok shortens the skirt and simplifies fastenings for everyday use.', 'https://en.wikipedia.org/wiki/Special:Search?search=Hanbok&go=Go') on conflict (slug) do update set name = excluded.name, country_id = excluded.country_id, summary = excluded.summary, textiles = excluded.textiles, craftsmanship = excluded.craftsmanship, wearing = excluded.wearing, contemporary = excluded.contemporary, source_url = excluded.source_url;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'lunar-new-year'), (select id from public.attire where slug = 'hanbok')) on conflict do nothing;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'mid-autumn-festival'), (select id from public.attire where slug = 'hanbok')) on conflict do nothing;
insert into public.attire (slug, name, country_id, summary, textiles, craftsmanship, wearing, contemporary, source_url) values ('kimono-yukata', 'Kimono and yukata', (select id from public.countries where code = 'JP'), 'The kimono is Japan''s formal wrapped robe; the yukata is its light cotton summer form, worn to festivals.', array['Silk', 'Cotton', 'Hemp']::text[], 'Dyeing techniques such as yuzen and shibori, and woven obi from Nishijin in Kyoto, are highly regarded.', 'Wrap left side over right. Yukata are the easy choice for summer festivals and are widely rented.', 'Designers use denim, wool and bold prints, and pair kimono with boots.', 'https://en.wikipedia.org/wiki/Special:Search?search=Kimono&go=Go') on conflict (slug) do update set name = excluded.name, country_id = excluded.country_id, summary = excluded.summary, textiles = excluded.textiles, craftsmanship = excluded.craftsmanship, wearing = excluded.wearing, contemporary = excluded.contemporary, source_url = excluded.source_url;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'gion-matsuri'), (select id from public.attire where slug = 'kimono-yukata')) on conflict do nothing;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'hanami'), (select id from public.attire where slug = 'kimono-yukata')) on conflict do nothing;
insert into public.attire (slug, name, country_id, summary, textiles, craftsmanship, wearing, contemporary, source_url) values ('ao-dai', 'Áo dài', (select id from public.countries where code = 'VN'), 'A long, close-fitting tunic split at the sides and worn over trousers.', array['Silk', 'Brocade', 'Velvet']::text[], 'Tailored to the wearer; hand-painted and embroidered versions are made for Tết.', 'Worn by women and men for Tết visits and photographs among the blossom.', 'Shorter, looser versions called áo dài cách tân are popular with younger wearers.', 'https://en.wikipedia.org/wiki/Special:Search?search=%C3%81o%20d%C3%A0i&go=Go') on conflict (slug) do update set name = excluded.name, country_id = excluded.country_id, summary = excluded.summary, textiles = excluded.textiles, craftsmanship = excluded.craftsmanship, wearing = excluded.wearing, contemporary = excluded.contemporary, source_url = excluded.source_url;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'lunar-new-year'), (select id from public.attire where slug = 'ao-dai')) on conflict do nothing;
insert into public.attire (slug, name, country_id, summary, textiles, craftsmanship, wearing, contemporary, source_url) values ('chut-thai', 'Chut thai', (select id from public.countries where code = 'TH'), 'Thai formal dress in several codified styles, with a wrapped skirt and shoulder cloth for women.', array['Thai silk', 'Mudmee ikat', 'Cotton']::text[], 'Handwoven silk from the north-east is prized for its texture and sheen.', 'At Songkran many people wear light floral shirts or traditional dress for temple visits.', 'Thai textiles are increasingly used in contemporary tailoring.', 'https://en.wikipedia.org/wiki/Special:Search?search=Formal%20Thai%20national%20costume&go=Go') on conflict (slug) do update set name = excluded.name, country_id = excluded.country_id, summary = excluded.summary, textiles = excluded.textiles, craftsmanship = excluded.craftsmanship, wearing = excluded.wearing, contemporary = excluded.contemporary, source_url = excluded.source_url;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'songkran'), (select id from public.attire where slug = 'chut-thai')) on conflict do nothing;
insert into public.attire (slug, name, country_id, summary, textiles, craftsmanship, wearing, contemporary, source_url) values ('tracht', 'Dirndl and lederhosen', (select id from public.countries where code = 'DE'), 'Alpine folk dress: a bodice, blouse, skirt and apron for women, leather breeches for men.', array['Linen', 'Cotton', 'Loden wool', 'Deerskin leather']::text[], 'Good lederhosen are embroidered by hand and last decades.', 'By popular custom the side on which the apron bow is tied signals whether the wearer is single or attached.', 'Shorter ''festival'' dirndls are widely sold, though many locals prefer traditional lengths.', 'https://en.wikipedia.org/wiki/Special:Search?search=Dirndl&go=Go') on conflict (slug) do update set name = excluded.name, country_id = excluded.country_id, summary = excluded.summary, textiles = excluded.textiles, craftsmanship = excluded.craftsmanship, wearing = excluded.wearing, contemporary = excluded.contemporary, source_url = excluded.source_url;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'oktoberfest'), (select id from public.attire where slug = 'tracht')) on conflict do nothing;
insert into public.attire (slug, name, country_id, summary, textiles, craftsmanship, wearing, contemporary, source_url) values ('mantilla', 'Mantilla', (select id from public.countries where code = 'ES'), 'A lace veil worn over a high comb, in black for Holy Week.', array['Blonde lace', 'Chantilly lace', 'Tortoiseshell-style comb']::text[], 'Fine mantillas are handmade lace heirlooms passed through families.', 'Worn with a black dress on Holy Thursday and Good Friday; it is mourning dress, not costume.', 'White mantillas appear at weddings and spring fairs.', 'https://en.wikipedia.org/wiki/Special:Search?search=Mantilla&go=Go') on conflict (slug) do update set name = excluded.name, country_id = excluded.country_id, summary = excluded.summary, textiles = excluded.textiles, craftsmanship = excluded.craftsmanship, wearing = excluded.wearing, contemporary = excluded.contemporary, source_url = excluded.source_url;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'semana-santa'), (select id from public.attire where slug = 'mantilla')) on conflict do nothing;
insert into public.attire (slug, name, country_id, summary, textiles, craftsmanship, wearing, contemporary, source_url) values ('fantasia', 'Carnival fantasia', (select id from public.countries where code = 'BR'), 'The costume of a samba school parader, designed each year around the school''s theme.', array['Feathers', 'Sequins', 'Beads', 'Lightweight frames']::text[], 'Workshops in each school''s barracão build thousands of costumes by hand in the months before carnival.', 'Street parties are relaxed: any bright, playful outfit fits in.', 'Schools increasingly use synthetic feathers and recycled materials.', 'https://en.wikipedia.org/wiki/Special:Search?search=Rio%20Carnival&go=Go') on conflict (slug) do update set name = excluded.name, country_id = excluded.country_id, summary = excluded.summary, textiles = excluded.textiles, craftsmanship = excluded.craftsmanship, wearing = excluded.wearing, contemporary = excluded.contemporary, source_url = excluded.source_url;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'rio-carnival'), (select id from public.attire where slug = 'fantasia')) on conflict do nothing;
insert into public.attire (slug, name, country_id, summary, textiles, craftsmanship, wearing, contemporary, source_url) values ('habesha-kemis', 'Habesha kemis', (select id from public.countries where code = 'ET'), 'An ankle-length white cotton dress with woven borders, worn with a shawl (netela).', array['Handwoven cotton (shemma)', 'Coloured tibeb borders']::text[], 'The tibeb border is woven on narrow looms in intricate geometric patterns.', 'White is worn by both women and men to Timkat processions.', 'Designers shorten hems and add colour while keeping the handwoven cloth.', 'https://en.wikipedia.org/wiki/Special:Search?search=Habesha%20kemis&go=Go') on conflict (slug) do update set name = excluded.name, country_id = excluded.country_id, summary = excluded.summary, textiles = excluded.textiles, craftsmanship = excluded.craftsmanship, wearing = excluded.wearing, contemporary = excluded.contemporary, source_url = excluded.source_url;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'timkat'), (select id from public.attire where slug = 'habesha-kemis')) on conflict do nothing;
insert into public.attire (slug, name, country_id, summary, textiles, craftsmanship, wearing, contemporary, source_url) values ('deel', 'Deel', (select id from public.countries where code = 'MN'), 'A long wrapped robe with a high collar, tied with a sash and worn by herders and city-dwellers alike.', array['Silk', 'Cotton', 'Sheepskin lining for winter']::text[], 'Cut, trim and hat style identify regions and ethnic groups.', 'Families dress in their best deel for Naadam''s opening ceremony.', 'Tailors make fitted, lighter deel for urban wear.', 'https://en.wikipedia.org/wiki/Special:Search?search=Deel%20(clothing)&go=Go') on conflict (slug) do update set name = excluded.name, country_id = excluded.country_id, summary = excluded.summary, textiles = excluded.textiles, craftsmanship = excluded.craftsmanship, wearing = excluded.wearing, contemporary = excluded.contemporary, source_url = excluded.source_url;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'naadam'), (select id from public.attire where slug = 'deel')) on conflict do nothing;
insert into public.attire (slug, name, country_id, summary, textiles, craftsmanship, wearing, contemporary, source_url) values ('kente', 'Kente', (select id from public.countries where code = 'GH'), 'Strip-woven cloth from the Asante and Ewe peoples of Ghana, with patterns that carry names and meanings.', array['Silk', 'Cotton', 'Rayon']::text[], 'Narrow strips are woven on horizontal looms and sewn edge to edge.', 'In Ghana it is prestige cloth for important occasions. In the diaspora, kente stoles and accents are worn at Kwanzaa and graduations.', 'Printed kente patterns are common; handwoven cloth remains the mark of quality.', 'https://en.wikipedia.org/wiki/Special:Search?search=Kente%20cloth&go=Go') on conflict (slug) do update set name = excluded.name, country_id = excluded.country_id, summary = excluded.summary, textiles = excluded.textiles, craftsmanship = excluded.craftsmanship, wearing = excluded.wearing, contemporary = excluded.contemporary, source_url = excluded.source_url;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'kwanzaa'), (select id from public.attire where slug = 'kente')) on conflict do nothing;
insert into public.attire (slug, name, country_id, summary, textiles, craftsmanship, wearing, contemporary, source_url) values ('midsommarkrans', 'Midsummer flower crown', (select id from public.countries where code = 'SE'), 'A wreath of wildflowers and birch leaves made on the morning of Midsummer Eve.', array['Wildflowers', 'Birch twigs', 'Florist''s wire']::text[], 'Traditionally made from whatever grows nearby.', 'Worn by everyone, usually with light summer clothes or regional folk dress.', 'Florists sell ready-made crowns in the cities.', 'https://en.wikipedia.org/wiki/Special:Search?search=Midsummer&go=Go') on conflict (slug) do update set name = excluded.name, country_id = excluded.country_id, summary = excluded.summary, textiles = excluded.textiles, craftsmanship = excluded.craftsmanship, wearing = excluded.wearing, contemporary = excluded.contemporary, source_url = excluded.source_url;
insert into public.festival_attire (festival_id, attire_id) values ((select id from public.festivals where slug = 'midsummer'), (select id from public.attire where slug = 'midsommarkrans')) on conflict do nothing;
