insert into public.brands (slug, name, origin, tier, categories, about, known_for, official_url, is_partner, source_url) values ('anita-dongre', 'Anita Dongre', 'India', 'premium', array['fashion', 'jewellery']::text[], 'The label of Mumbai designer Anita Dongre, known for lehengas and for work with craft communities.', array['Lightweight lehengas', 'Hand embroidery', 'Occasion wear']::text[], 'https://www.anitadongre.com/', false, 'https://en.wikipedia.org/wiki/Special:Search?search=Anita%20Dongre&go=Go') on conflict (slug) do update set name = excluded.name, origin = excluded.origin, tier = excluded.tier, categories = excluded.categories, about = excluded.about, known_for = excluded.known_for, official_url = excluded.official_url, source_url = excluded.source_url;
